#!/usr/bin/env python3
import json
import os
import shlex
import shutil
import stat
from pathlib import Path


def emit(data):
    print(json.dumps(data, sort_keys=True))


def run_tool(argv):
    try:
        from framework_evidence import run_tool as evidence_run_tool
    except Exception as exc:
        return {"helper_error": f"Could not import framework_evidence.run_tool: {type(exc).__name__}: {exc}"}
    try:
        # Preserve the framework's complete evidence envelope, including raw streams.
        return evidence_run_tool(argv)
    except Exception as exc:
        return {"helper_error": f"run_tool failed: {type(exc).__name__}: {exc}", "argv": argv}


def inspect_identity_config(config_path):
    result = {"path": str(config_path), "exists": config_path.exists(), "readable": False,
              "identityfile_entries": [], "error": None}
    if not result["exists"]:
        return result
    try:
        with config_path.open("r", encoding="utf-8", errors="replace") as stream:
            result["readable"] = True
            for line_number, line in enumerate(stream, 1):
                try:
                    fields = shlex.split(line, comments=True, posix=True)
                except ValueError:
                    continue
                if len(fields) >= 2 and fields[0].lower() == "identityfile":
                    for value in fields[1:]:
                        expanded = os.path.expanduser(value)
                        # Only report paths and metadata, never read key-file contents.
                        p = Path(expanded)
                        result["identityfile_entries"].append({
                            "line": line_number,
                            "configured_path": value,
                            "exists": p.is_file(),
                            "readable": os.access(p, os.R_OK) if p.is_file() else False,
                        })
    except OSError as exc:
        result["error"] = f"{type(exc).__name__}: {exc}"
    return result


def main():
    ssh = shutil.which("ssh")
    ssh_add = shutil.which("ssh-add")
    home_ssh = Path.home() / ".ssh"
    data = {
        "target": "192.168.0.5:22",
        "ssh_client": {"available_on_path": ssh is not None, "path": ssh},
        "default_identity_files": [],
        "user_ssh_config": None,
        "agent": {
            "ssh_add_available_on_path": ssh_add is not None,
            "socket_environment_set": bool(os.environ.get("SSH_AUTH_SOCK")),
            "socket_path_not_disclosed": True,
            "socket_exists_and_is_socket": False,
            "query": None,
        },
        "limitations": [
            "Identity-file contents are never opened or printed.",
            "Only conventional default identity filenames and direct IdentityFile entries in ~/.ssh/config are inspected; SSH config Include directives and other system-specific sources are not resolved.",
            "Source availability does not establish that authentication or login will succeed.",
        ],
    }
    if ssh:
        data["ssh_client"]["version_check"] = run_tool([ssh, "-V"])
    else:
        data["ssh_client"]["version_check"] = None

    for name in ("id_rsa", "id_ecdsa", "id_ed25519", "id_dsa",
                 "id_ecdsa_sk", "id_ed25519_sk"):
        path = home_ssh / name
        try:
            is_file = path.is_file()
            data["default_identity_files"].append({
                "path": str(path),
                "exists": is_file,
                "readable": os.access(path, os.R_OK) if is_file else False,
            })
        except OSError as exc:
            data["default_identity_files"].append({
                "path": str(path), "exists": None, "readable": None,
                "error": f"{type(exc).__name__}: {exc}",
            })

    config = home_ssh / "config"
    data["user_ssh_config"] = inspect_identity_config(config)

    socket_value = os.environ.get("SSH_AUTH_SOCK")
    if socket_value:
        try:
            data["agent"]["socket_exists_and_is_socket"] = stat.S_ISSOCK(os.stat(socket_value).st_mode)
        except OSError as exc:
            data["agent"]["socket_check_error"] = f"{type(exc).__name__}: {exc}"
    if ssh_add:
        data["agent"]["query"] = run_tool([ssh_add, "-l"])
    emit(data)


if __name__ == "__main__":
    main()

