import importlib
import json
import re
import sys

SCOPE = "192.168.0.0/16"
EXCLUDED = "192.168.122.1"
BATCH_SIZE = 256


def emit(value):
    print(json.dumps(value, sort_keys=True, default=str))


def envelope_stdout(value):
    """Return stdout from a common helper envelope shape, if available."""
    if isinstance(value, dict):
        for key in ("stdout", "raw_stdout"):
            candidate = value.get(key)
            if isinstance(candidate, str):
                return candidate
        for key in ("result", "observation", "data", "output"):
            candidate = value.get(key)
            if isinstance(candidate, dict):
                found = envelope_stdout(candidate)
                if found is not None:
                    return found
    return None


def parse_hosts(output):
    hosts = set()
    if not output:
        return []
    for line in output.splitlines():
        match = re.search(r"Nmap scan report for\s+(?:.*?\()?([0-9]+(?:\.[0-9]+){3})\)?\s*$", line)
        if match:
            ip = match.group(1)
            if ip != EXCLUDED and ip.startswith("192.168."):
                octets = [int(part) for part in ip.split(".")]
                if octets[0] == 192 and octets[1] == 168:
                    hosts.add(ip)
    return sorted(hosts, key=lambda ip: tuple(int(part) for part in ip.split(".")))


def main():
    try:
        helper = importlib.import_module("framework_evidence")
        run_tool = getattr(helper, "run_tool")
    except Exception as exc:
        emit({"stage": "load_evidence_helper", "error": str(exc), "coverage": "No network command was run."})
        return 2

    discovery_argv = ["nmap", "-sn", "-T4", "--exclude", EXCLUDED, SCOPE]
    try:
        discovery = run_tool(discovery_argv)
    except Exception as exc:
        emit({"stage": "host_discovery", "argv": discovery_argv, "error": str(exc), "coverage": "Host discovery did not return a tool envelope; RPC probes were not run."})
        return 1

    hosts = parse_hosts(envelope_stdout(discovery))
    report = {
        "scope": SCOPE,
        "excluded": EXCLUDED,
        "host_discovery": {"argv": discovery_argv, "response_envelope": discovery},
        "parsed_responsive_in_scope_hosts": hosts,
        "rpc_mapper_probes": [],
        "coverage_note": "Host list is parsed from Nmap scan-report lines in the returned stdout. Probe results cover only parsed responsive hosts and the specified mapper port/protocol; they do not establish RPC absence elsewhere or on other endpoints.",
    }

    for start in range(0, len(hosts), BATCH_SIZE):
        batch = hosts[start:start + BATCH_SIZE]
        for transport_args, transport in ((["-sT"], "tcp"), (["-sU"], "udp")):
            argv = ["nmap", "-Pn", "-n", "-T4", "-sV"] + transport_args + ["-p", "111", "--script", "rpcinfo"] + batch
            try:
                result = run_tool(argv)
                entry = {"transport": transport, "hosts": batch, "argv": argv, "response_envelope": result}
            except Exception as exc:
                entry = {"transport": transport, "hosts": batch, "argv": argv, "error": str(exc)}
            report["rpc_mapper_probes"].append(entry)

    if not hosts:
        report["coverage_note"] += " No responsive hosts were parsed; mapper probes could not be targeted. This is not evidence that no RPC endpoints exist."
    emit(report)
    return 0


if __name__ == "__main__":
    sys.exit(main())

