#!/usr/bin/env python3
import concurrent.futures
import json
import secrets
import socket
import struct
import sys
import xml.etree.ElementTree as ET

NETWORK = "192.168.0.0/16"
EXCLUDE = "192.168.122.1"
PORT = 111
TIMEOUT = 1.5


def find_nmap_xml(value):
    if isinstance(value, str):
        if "<nmaprun" in value:
            start = value.find("<nmaprun")
            end = value.find("</nmaprun>", start)
            if end >= 0:
                return value[start:end + len("</nmaprun>")]
        return None
    if isinstance(value, dict):
        for item in value.values():
            found = find_nmap_xml(item)
            if found:
                return found
    elif isinstance(value, list):
        for item in value:
            found = find_nmap_xml(item)
            if found:
                return found
    return None


def rpc_call(xid):
    # ONC RPC CALL: rpcbind/portmapper program 100000, v2, DUMP procedure 4.
    words = (xid, 0, 2, 100000, 2, 4, 0, 0, 0, 0)
    return struct.pack("!10I", *words)


def read_exact(sock, count):
    chunks = []
    remaining = count
    while remaining:
        chunk = sock.recv(remaining)
        if not chunk:
            raise ConnectionError("connection closed before complete RPC record")
        chunks.append(chunk)
        remaining -= len(chunk)
    return b"".join(chunks)


def parse_reply(data, xid):
    if len(data) < 12:
        raise ValueError("RPC reply shorter than minimum header")
    rxid, msg_type, reply_stat = struct.unpack_from("!3I", data, 0)
    if rxid != xid:
        raise ValueError("reply XID did not match request")
    if msg_type != 1:
        raise ValueError("message was not an RPC REPLY")
    if reply_stat != 0:
        return {"rpc_reply_status": reply_stat, "detail": "MSG_DENIED or unknown reply status"}
    if len(data) < 24:
        raise ValueError("accepted RPC reply lacks verifier and accept status")
    verifier_len = struct.unpack_from("!I", data, 16)[0]
    offset = 20 + verifier_len + ((4 - verifier_len % 4) % 4)
    if len(data) < offset + 4:
        raise ValueError("accepted RPC reply truncated before accept status")
    accept_stat = struct.unpack_from("!I", data, offset)[0]
    offset += 4
    result = {"rpc_reply_status": "accepted", "accept_status": accept_stat}
    if accept_stat != 0:
        result["detail"] = "RPC call was not accepted as SUCCESS"
        return result

    mappings = []
    # Portmapper DUMP result is a linked list: bool, then pmap (prog, vers, prot, port).
    while True:
        if len(data) < offset + 4:
            raise ValueError("truncated DUMP linked-list indicator")
        present = struct.unpack_from("!I", data, offset)[0]
        offset += 4
        if present == 0:
            break
        if len(data) < offset + 16:
            raise ValueError("truncated portmapper mapping record")
        program, version, protocol, port = struct.unpack_from("!4I", data, offset)
        offset += 16
        mappings.append({"program": program, "version": version,
                         "protocol": protocol, "port": port})
    result["mappings"] = mappings
    return result


def direct_probe(host, transport):
    xid = secrets.randbits(32)
    request = rpc_call(xid)
    outcome = {"host": host, "transport": transport, "port": PORT,
               "request": "ONC RPC portmapper v2 DUMP (program 100000, procedure 4)"}
    try:
        with socket.socket(socket.AF_INET,
                           socket.SOCK_DGRAM if transport == "udp" else socket.SOCK_STREAM) as sock:
            sock.settimeout(TIMEOUT)
            if transport == "udp":
                sock.sendto(request, (host, PORT))
                data, peer = sock.recvfrom(65535)
                outcome["peer"] = list(peer)
            else:
                sock.connect((host, PORT))
                sock.sendall(struct.pack("!I", 0x80000000 | len(request)) + request)
                marker = struct.unpack("!I", read_exact(sock, 4))[0]
                record_len = marker & 0x7fffffff
                parts = [read_exact(sock, record_len)]
                while not (marker & 0x80000000):
                    marker = struct.unpack("!I", read_exact(sock, 4))[0]
                    parts.append(read_exact(sock, marker & 0x7fffffff))
                data = b"".join(parts)
        outcome["response_bytes"] = len(data)
        outcome["response"] = parse_reply(data, xid)
    except Exception as exc:
        outcome["error"] = type(exc).__name__ + ": " + str(exc)
    return outcome


def main():
    try:
        import framework_evidence
    except Exception as exc:
        print(json.dumps({"status": "blocked_at_runtime", "stage": "load_evidence_helper",
                          "error": type(exc).__name__ + ": " + str(exc),
                          "coverage": "No host discovery or direct RPC requests were made."}))
        return 2

    argv = ["nmap", "-n", "-sn", "-PE", "-PS111", "-PU111", "-T4",
            "--max-retries", "1", "--host-timeout", "8s", "--exclude", EXCLUDE,
            "-oX", "-", NETWORK]
    try:
        envelope = framework_evidence.run_tool(argv)
    except Exception as exc:
        print(json.dumps({"status": "scan_error", "command": argv,
                          "error": type(exc).__name__ + ": " + str(exc),
                          "coverage": "Host discovery did not yield candidate hosts; no direct RPC requests were made."}))
        return 1

    # Preserve the helper's complete evidence envelope, including raw streams/status.
    print(json.dumps({"evidence_envelope": envelope}, ensure_ascii=False, default=str))
    xml_text = find_nmap_xml(envelope)
    if not xml_text:
        print(json.dumps({"status": "incomplete", "coverage": {
            "scope": NETWORK, "excluded": EXCLUDE,
            "host_discovery_command": argv,
            "direct_requests": 0,
            "limitation": "No Nmap XML was available in the evidence envelope; no direct RPC requests were made."}}))
        return 1

    try:
        root = ET.fromstring(xml_text)
        hosts = sorted({h.findtext("address[@addrtype='ipv4']")
                        for h in root.findall("host")
                        if h.findtext("status/@state") == "up"})
        # ElementTree does not support the status/@state path in findtext on all Python versions.
        if not hosts:
            hosts = sorted({h.find("address[@addrtype='ipv4']").get("addr")
                            for h in root.findall("host")
                            if h.find("status") is not None and h.find("status").get("state") == "up"
                            and h.find("address[@addrtype='ipv4']") is not None})
        hosts = [h for h in hosts if h and h != EXCLUDE]
    except Exception as exc:
        print(json.dumps({"status": "parse_error", "error": type(exc).__name__ + ": " + str(exc),
                          "coverage": "Nmap ran, but its XML could not be parsed; no direct RPC requests were made."}))
        return 1

    requests = [(host, transport) for host in hosts for transport in ("tcp", "udp")]
    results = []
    with concurrent.futures.ThreadPoolExecutor(max_workers=64) as pool:
        futures = [pool.submit(direct_probe, host, transport) for host, transport in requests]
        for future in concurrent.futures.as_completed(futures):
            results.append(future.result())
    results.sort(key=lambda x: (x["host"], x["transport"]))
    report = {
        "status": "completed",
        "coverage": {
            "scope": NETWORK,
            "excluded": EXCLUDE,
            "discovery_method": "Nmap ICMP echo, TCP SYN to 111, and UDP probe to 111 host discovery",
            "responsive_hosts_discovered": hosts,
            "direct_rpc_requests_attempted": len(requests),
            "per_host_transports_attempted": ["tcp", "udp"],
            "timeout_seconds_per_request": TIMEOUT,
            "limitations": [
                "Only discovered responsive hosts were queried, and only port 111 was attempted.",
                "These results do not establish availability or absence of RPC services on other ports or endpoints.",
                "Exact endpoints from the partial prior-evidence preview were unavailable to this action."
            ]
        },
        "direct_responses": results
    }
    print(json.dumps(report, ensure_ascii=False))
    return 0


if __name__ == "__main__":
    sys.exit(main())

