#!/usr/bin/env python3
"""Find TCP/111 candidates in scope and make direct ONC RPC DUMP requests."""
import json
import socket
import struct
import sys
import xml.etree.ElementTree as ET

SCOPE = "192.168.0.0/16"
EXCLUDED = "192.168.122.1"
TIMEOUT = 1.5


def extract_stdout(value):
    """Find a stdout string in common framework_evidence envelope shapes."""
    if isinstance(value, dict):
        for key in ("stdout", "raw_stdout"):
            if isinstance(value.get(key), str):
                return value[key]
        for key in ("execution_result", "result", "data", "observation"):
            if key in value:
                found = extract_stdout(value[key])
                if found is not None:
                    return found
    return None


def rpc_call(xid):
    # ONC RPC v2: CALL, rpcbind/portmapper program 100000 v2, DUMP procedure 4.
    return struct.pack("!10I", xid, 0, 2, 100000, 2, 4, 0, 0, 0, 0)


def parse_dump(data, xid):
    """Parse an RPC reply and XDR portmapper DUMP list, retaining failures."""
    if len(data) < 24:
        raise ValueError("short RPC reply (%d bytes)" % len(data))
    offset = 0

    def take_u32():
        nonlocal offset
        if offset + 4 > len(data):
            raise ValueError("truncated XDR reply at byte %d" % offset)
        value = struct.unpack_from("!I", data, offset)[0]
        offset += 4
        return value

    actual_xid = take_u32()
    msg_type = take_u32()
    if actual_xid != xid:
        raise ValueError("reply XID mismatch")
    if msg_type != 1:
        raise ValueError("message is not an RPC REPLY")
    reply_stat = take_u32()
    if reply_stat != 0:
        raise ValueError("RPC message rejected (reply_stat=%d)" % reply_stat)
    auth_flavor = take_u32()
    auth_len = take_u32()
    padded = (auth_len + 3) & ~3
    if offset + padded > len(data):
        raise ValueError("truncated RPC verifier")
    offset += padded
    accept_stat = take_u32()
    if accept_stat != 0:
        raise ValueError("RPC call not accepted (accept_stat=%d)" % accept_stat)
    mappings = []
    while True:
        more = take_u32()
        if more == 0:
            break
        mappings.append({
            "program": take_u32(),
            "version": take_u32(),
            "protocol": take_u32(),
            "port": take_u32(),
        })
    return {"xid": actual_xid, "verifier_flavor": auth_flavor,
            "mappings": mappings}


def tcp_dump(host, xid):
    request = rpc_call(xid)
    record = struct.pack("!I", 0x80000000 | len(request)) + request
    with socket.create_connection((host, 111), timeout=TIMEOUT) as sock:
        sock.settimeout(TIMEOUT)
        sock.sendall(record)
        chunks = bytearray()
        final = False
        while not final:
            marker = recv_exact(sock, 4)
            value = struct.unpack("!I", marker)[0]
            final = bool(value & 0x80000000)
            remaining = value & 0x7fffffff
            if remaining > 1_000_000:
                raise ValueError("RPC record fragment exceeds 1 MB")
            chunks.extend(recv_exact(sock, remaining))
        return parse_dump(bytes(chunks), xid)


def recv_exact(sock, length):
    result = bytearray()
    while len(result) < length:
        part = sock.recv(length - len(result))
        if not part:
            raise ConnectionError("peer closed before complete RPC record")
        result.extend(part)
    return bytes(result)


def udp_dump(host, xid):
    request = rpc_call(xid)
    with socket.socket(socket.AF_INET, socket.SOCK_DGRAM) as sock:
        sock.settimeout(TIMEOUT)
        sock.sendto(request, (host, 111))
        data, peer = sock.recvfrom(65535)
    return {"peer": peer[0], **parse_dump(data, xid)}


def main():
    try:
        from framework_evidence import run_tool
    except Exception as exc:
        print(json.dumps({"status": "blocked", "obstacle":
                          "framework_evidence.run_tool could not be imported",
                          "error": str(exc)}, sort_keys=True))
        return 2

    argv = ["nmap", "-n", "-sT", "-p", "111", "--open", "--reason",
            "-T4", "--min-rate", "2000", "--host-timeout", "5s",
            "--exclude", EXCLUDED, "-oX", "-", SCOPE]
    try:
        envelope = run_tool(argv)
    except Exception as exc:
        print(json.dumps({"status": "tool_error", "argv": argv,
                          "error": str(exc)}, sort_keys=True))
        return 1

    # Preserve and emit the framework's original evidence envelope.
    try:
        print(json.dumps(envelope, sort_keys=True, default=str))
    except Exception:
        print(json.dumps({"unserializable_envelope": repr(envelope)}))

    xml_text = extract_stdout(envelope)
    report = {
        "scope": SCOPE,
        "excluded": EXCLUDED,
        "nmap_argv": argv,
        "scan_envelope_status": (envelope.get("status")
                                 if isinstance(envelope, dict) else None),
        "xml_parse": "not_attempted",
        "tcp_111_candidates": [],
        "direct_rpc_attempts": [],
        "coverage_note": "Candidate hosts are limited to those reported with TCP/111 open by this scan. UDP/111 is tested only on those candidates. Other RPC ports and hosts not reported by the scan are not assessed.",
    }
    if not isinstance(xml_text, str) or not xml_text.strip():
        report["xml_parse"] = "no XML stdout available"
        report["status"] = "incomplete"
        print(json.dumps(report, sort_keys=True))
        return 0
    try:
        root = ET.fromstring(xml_text)
        for host_el in root.findall("host"):
            addr_el = host_el.find("address[@addrtype='ipv4']")
            if addr_el is None:
                continue
            ip = addr_el.get("addr")
            if not ip or ip == EXCLUDED:
                continue
            for port_el in host_el.findall("ports/port"):
                state_el = port_el.find("state")
                if (port_el.get("protocol") == "tcp" and
                        port_el.get("portid") == "111" and state_el is not None and
                        state_el.get("state") == "open"):
                    report["tcp_111_candidates"].append(ip)
                    break
        report["tcp_111_candidates"] = sorted(set(report["tcp_111_candidates"]))
        report["xml_parse"] = "success"
        report["nmap_run_stats"] = {
            "finished": (root.find("runstats/finished").attrib
                         if root.find("runstats/finished") is not None else None),
            "hosts": (root.find("runstats/hosts").attrib
                      if root.find("runstats/hosts") is not None else None),
        }
    except Exception as exc:
        report["xml_parse"] = "failed: %s" % exc
        report["status"] = "incomplete"
        print(json.dumps(report, sort_keys=True))
        return 0

    for index, host in enumerate(report["tcp_111_candidates"], 1):
        item = {"host": host, "port": 111, "protocol": "ONC RPC portmapper",
                "requests": {}}
        for transport in ("tcp", "udp"):
            xid = (0x52504300 + index * 2 + (transport == "udp")) & 0xffffffff
            try:
                response = tcp_dump(host, xid) if transport == "tcp" else udp_dump(host, xid)
                item["requests"][transport] = {"outcome": "rpc_reply", **response}
            except Exception as exc:
                item["requests"][transport] = {
                    "outcome": "no_usable_reply_or_transport_error",
                    "error_type": type(exc).__name__, "error": str(exc),
                }
        report["direct_rpc_attempts"].append(item)
    report["status"] = "completed_requests" if report["xml_parse"] == "success" else "incomplete"
    print(json.dumps(report, sort_keys=True))
    return 0


if __name__ == "__main__":
    sys.exit(main())

