import json
import socket
import struct
import secrets

HOSTS = ["192.168.0.1", "192.168.65.3", "192.168.65.6"]
EXCLUDED = "192.168.122.1"
PORT = 111
TIMEOUT = 2.5


def u32(value):
    return struct.pack("!I", value)


def make_call(xid, version):
    # ONC RPC CALL, AUTH_NULL credentials and verifier; portmapper/rpcbind DUMP.
    fields = [xid, 0, 2, 100000, version, 4, 0, 0, 0, 0]
    return b"".join(u32(value) for value in fields)


class XDR:
    def __init__(self, data, offset=0):
        self.data = data
        self.offset = offset

    def uint(self):
        if self.offset + 4 > len(self.data):
            raise ValueError("truncated XDR uint")
        value = struct.unpack_from("!I", self.data, self.offset)[0]
        self.offset += 4
        return value

    def string(self):
        length = self.uint()
        end = self.offset + length
        if end > len(self.data):
            raise ValueError("truncated XDR string")
        value = self.data[self.offset:end].decode("utf-8", errors="replace")
        self.offset = end + ((-length) % 4)
        if self.offset > len(self.data):
            raise ValueError("truncated XDR string padding")
        return value


def decode_reply(data, xid, version):
    x = XDR(data)
    got_xid = x.uint()
    if got_xid != xid:
        raise ValueError("response transaction ID does not match request")
    message_type = x.uint()
    if message_type != 1:
        raise ValueError("RPC response has unexpected message type %d" % message_type)
    reply_status = x.uint()
    if reply_status != 0:
        result = {"rpc_reply_status": reply_status}
        if reply_status == 1 and x.offset + 4 <= len(data):
            result["reject_status"] = x.uint()
        return result

    verifier_flavor = x.uint()
    verifier_length = x.uint()
    verifier_end = x.offset + verifier_length
    if verifier_end > len(data):
        raise ValueError("truncated RPC verifier")
    x.offset = verifier_end + ((-verifier_length) % 4)
    accept_status = x.uint()
    result = {
        "rpc_reply_status": "accepted",
        "verifier_flavor": verifier_flavor,
        "accept_status": accept_status,
    }
    if accept_status != 0:
        return result

    mappings = []
    # PMAPPROC_DUMP v2 returns a linked list of pmap structs.
    # RPCBPROC_DUMP v3/v4 returns a linked list of rpcb structs.
    for _ in range(4096):
        present = x.uint()
        if present == 0:
            result["mappings"] = mappings
            result["trailing_bytes"] = len(data) - x.offset
            return result
        if version == 2:
            mappings.append({
                "program": x.uint(),
                "version": x.uint(),
                "protocol": x.uint(),
                "port": x.uint(),
            })
        else:
            mappings.append({
                "program": x.uint(),
                "version": x.uint(),
                "netid": x.string(),
                "address": x.string(),
                "owner": x.string(),
            })
    raise ValueError("mapping list exceeded 4096 entries")


def recv_exact(sock, size):
    chunks = []
    remaining = size
    while remaining:
        chunk = sock.recv(remaining)
        if not chunk:
            raise ConnectionError("connection closed before complete RPC record")
        chunks.append(chunk)
        remaining -= len(chunk)
    return b"".join(chunks)


def recv_tcp_record(sock):
    fragments = []
    total = 0
    while True:
        marker = struct.unpack("!I", recv_exact(sock, 4))[0]
        length = marker & 0x7fffffff
        total += length
        if total > 4 * 1024 * 1024:
            raise ValueError("TCP RPC record exceeds 4 MiB")
        fragments.append(recv_exact(sock, length))
        if marker & 0x80000000:
            return b"".join(fragments)


def attempt(host, transport, version):
    xid = secrets.randbits(32)
    payload = make_call(xid, version)
    result = {
        "host": host,
        "endpoint": "%s:%d" % (host, PORT),
        "transport": transport,
        "rpc_program": 100000,
        "rpc_version": version,
        "procedure": "DUMP",
        "request_xid": xid,
    }
    try:
        if transport == "udp":
            with socket.socket(socket.AF_INET, socket.SOCK_DGRAM) as sock:
                sock.settimeout(TIMEOUT)
                sock.sendto(payload, (host, PORT))
                response, peer = sock.recvfrom(65535)
            result["peer"] = "%s:%d" % peer
        else:
            with socket.create_connection((host, PORT), timeout=TIMEOUT) as sock:
                sock.settimeout(TIMEOUT)
                sock.sendall(struct.pack("!I", 0x80000000 | len(payload)) + payload)
                response = recv_tcp_record(sock)
        result["raw_response_hex"] = response.hex()
        result["response_bytes"] = len(response)
        try:
            result["decoded"] = decode_reply(response, xid, version)
            result["status"] = "response_decoded"
        except Exception as exc:
            result["status"] = "response_received_parse_error"
            result["parse_error"] = "%s: %s" % (type(exc).__name__, exc)
    except Exception as exc:
        result["status"] = "request_error"
        result["error_type"] = type(exc).__name__
        result["error"] = str(exc)
    return result


def main():
    results = []
    for host in HOSTS:
        if host == EXCLUDED:
            continue
        for transport in ("udp", "tcp"):
            for version in (2, 3, 4):
                results.append(attempt(host, transport, version))
    print(json.dumps({
        "method": "direct ONC RPC portmapper/rpcbind DUMP",
        "scope_hosts": HOSTS,
        "endpoint_port": PORT,
        "excluded_host": EXCLUDED,
        "requests_planned": len(HOSTS) * 2 * 3,
        "requests_recorded": len(results),
        "timeout_seconds_per_request": TIMEOUT,
        "results": results,
    }, sort_keys=True))


if __name__ == "__main__":
    main()

