import json
import socket
import struct
import time

HOSTS = ["192.168.0.1", "192.168.65.3", "192.168.65.6"]
EXCLUDED = "192.168.122.1"
PORTMAPPER = 100000
RPCB_V2 = 2
DUMP_PROC = 4
TIMEOUT = 2.5


def pad4(data):
    return data + b"\x00" * ((-len(data)) % 4)


def u32(value):
    return struct.pack("!I", value & 0xffffffff)


def xdr_string(value):
    raw = value.encode("utf-8")
    return u32(len(raw)) + pad4(raw)


def rpc_call(program, version, procedure, args=b""):
    xid = int(time.time_ns()) & 0xffffffff
    packet = b"".join((
        u32(xid), u32(0), u32(2), u32(program), u32(version), u32(procedure),
        u32(0), u32(0), u32(0), u32(0), args
    ))
    return xid, packet


def read_tcp_record(sock):
    pieces = []
    while True:
        header = b""
        while len(header) < 4:
            part = sock.recv(4 - len(header))
            if not part:
                raise ConnectionError("connection closed while reading RPC record marker")
            header += part
        marker = struct.unpack("!I", header)[0]
        length = marker & 0x7fffffff
        last = bool(marker & 0x80000000)
        fragment = b""
        while len(fragment) < length:
            part = sock.recv(length - len(fragment))
            if not part:
                raise ConnectionError("connection closed during RPC record")
            fragment += part
        pieces.append(fragment)
        if last:
            return b"".join(pieces)


def rpc_exchange(host, port, transport, program, version, procedure, args=b""):
    xid, packet = rpc_call(program, version, procedure, args)
    if transport == "udp":
        with socket.socket(socket.AF_INET, socket.SOCK_DGRAM) as sock:
            sock.settimeout(TIMEOUT)
            sock.sendto(packet, (host, port))
            raw, peer = sock.recvfrom(65535)
    else:
        with socket.create_connection((host, port), timeout=TIMEOUT) as sock:
            sock.settimeout(TIMEOUT)
            sock.sendall(struct.pack("!I", 0x80000000 | len(packet)) + packet)
            raw = read_tcp_record(sock)
            peer = (host, port)
    result = {
        "host": host, "port": port, "transport": transport,
        "program": program, "version": version, "procedure": procedure,
        "request_xid": xid, "peer": str(peer), "response_bytes": len(raw),
        "raw_response_hex": raw.hex()
    }
    try:
        if len(raw) < 12:
            raise ValueError("RPC reply shorter than fixed header")
        rxid, msg_type, reply_stat = struct.unpack_from("!III", raw, 0)
        result.update({"reply_xid": rxid, "message_type": msg_type, "reply_status": reply_stat})
        if rxid != xid:
            raise ValueError("reply XID does not match request")
        if msg_type != 1:
            raise ValueError("message is not an RPC reply")
        if reply_stat != 0:
            result["rpc_accept_status"] = "denied"
            return result, b""
        if len(raw) < 24:
            raise ValueError("accepted RPC reply is truncated")
        flavor, auth_len = struct.unpack_from("!II", raw, 12)
        offset = 20 + auth_len + ((-auth_len) % 4)
        if len(raw) < offset + 4:
            raise ValueError("RPC verifier or accept status is truncated")
        accept_status = struct.unpack_from("!I", raw, offset)[0]
        result["verifier_flavor"] = flavor
        result["accept_status"] = accept_status
        result["rpc_accept_status"] = "accepted" if accept_status == 0 else "procedure_or_arguments_rejected"
        return result, raw[offset + 4:]
    except Exception as exc:
        result["parse_error"] = str(exc)
        return result, b""


class XDR:
    def __init__(self, data):
        self.data = data
        self.pos = 0

    def word(self):
        if self.pos + 4 > len(self.data):
            raise ValueError("truncated XDR uint32")
        value = struct.unpack_from("!I", self.data, self.pos)[0]
        self.pos += 4
        return value

    def string(self):
        length = self.word()
        end = self.pos + length
        if end > len(self.data):
            raise ValueError("truncated XDR string")
        value = self.data[self.pos:end].decode("utf-8", "replace")
        self.pos = end + ((-length) % 4)
        if self.pos > len(self.data):
            raise ValueError("truncated XDR string padding")
        return value


def decode_pmap_dump(data):
    reader = XDR(data)
    mappings = []
    while reader.word():
        mappings.append({
            "program": reader.word(), "version": reader.word(),
            "protocol": reader.word(), "port": reader.word()
        })
    return mappings


def decode_mount_exports(data):
    reader = XDR(data)
    exports = []
    while reader.word():
        path = reader.string()
        groups = []
        while reader.word():
            groups.append(reader.string())
        exports.append({"path": path, "groups": groups})
    return exports


def main():
    output = {
        "method": "RPC rpcbind v2 DUMP; NULL calls; MOUNT EXPORT where mapped",
        "scope_hosts": HOSTS, "excluded_host": EXCLUDED,
        "timeout_seconds_per_request": TIMEOUT,
        "results": [],
        "limitations": [
            "Only the listed previously evidenced hosts and mapper-reported endpoints were queried.",
            "MOUNT EXPORT lists server-advertised exports; it does not establish that a client can mount or read them.",
            "No MOUNT operation, file access, authentication attempt, or credential guessing was performed."
        ]
    }
    for host in HOSTS:
        host_result = {"host": host, "mapper_queries": [], "interactions": []}
        output["results"].append(host_result)
        if host == EXCLUDED:
            host_result["skipped"] = "explicitly excluded host"
            continue
        mappings = []
        for transport in ("udp", "tcp"):
            try:
                observed, body = rpc_exchange(host, 111, transport, PORTMAPPER, RPCB_V2, DUMP_PROC)
                if observed.get("accept_status") == 0:
                    try:
                        decoded = decode_pmap_dump(body)
                        observed["decoded_mappings"] = decoded
                        mappings.extend((transport, item) for item in decoded)
                    except Exception as exc:
                        observed["mapping_decode_error"] = str(exc)
                host_result["mapper_queries"].append(observed)
            except Exception as exc:
                host_result["mapper_queries"].append({
                    "host": host, "port": 111, "transport": transport,
                    "status": "error", "error": str(exc)
                })

        unique = set()
        for mapper_transport, item in mappings:
            proto = item["protocol"]
            endpoint_transport = "tcp" if proto == 6 else "udp" if proto == 17 else None
            port = item["port"]
            key = (item["program"], item["version"], endpoint_transport, port)
            if endpoint_transport is None or not port or key in unique:
                continue
            unique.add(key)
            base = {
                "program": item["program"], "version": item["version"],
                "transport": endpoint_transport, "port": port,
                "mapping_protocol": proto, "mapping_source_transport": mapper_transport
            }
            try:
                observed, _ = rpc_exchange(host, port, endpoint_transport,
                                           item["program"], item["version"], 0)
                base["null_call"] = observed
            except Exception as exc:
                base["null_call"] = {"status": "error", "error": str(exc)}

            if item["program"] == 100005 and item["version"] in (1, 3):
                try:
                    export_result, export_body = rpc_exchange(
                        host, port, endpoint_transport, 100005, item["version"], 5
                    )
                    if export_result.get("accept_status") == 0:
                        try:
                            export_result["decoded_exports"] = decode_mount_exports(export_body)
                        except Exception as exc:
                            export_result["export_decode_error"] = str(exc)
                    base["mount_export_call"] = export_result
                except Exception as exc:
                    base["mount_export_call"] = {"status": "error", "error": str(exc)}
            host_result["interactions"].append(base)

    print(json.dumps(output, sort_keys=True))


if __name__ == "__main__":
    main()

