import json
import socket
import struct
import sys
import time

EXCLUDED = "192.168.122.1"
HOSTS = ["192.168.0.1", "192.168.65.3", "192.168.65.6"]
TIMEOUT = 2.5

def u32(n):
    return struct.pack("!I", n & 0xffffffff)

def u64(n):
    return struct.pack("!Q", n & 0xffffffffffffffff)

def opaque(b):
    return u32(len(b)) + b + b"\0" * ((-len(b)) % 4)

def xdr_string(s):
    return opaque(s.encode())

class XDR:
    def __init__(self, data):
        self.data = data
        self.p = 0
    def take(self, n):
        if n < 0 or self.p + n > len(self.data):
            raise ValueError("truncated XDR value")
        b = self.data[self.p:self.p+n]
        self.p += n
        return b
    def u32(self):
        return struct.unpack("!I", self.take(4))[0]
    def u64(self):
        return struct.unpack("!Q", self.take(8))[0]
    def opaque(self):
        n = self.u32()
        b = self.take(n)
        self.take((-n) % 4)
        return b
    def string(self):
        return self.opaque().decode("utf-8", "replace")

def rpc_call(host, port, transport, program, version, procedure, args=b"", xid=None):
    xid = xid if xid is not None else int(time.time_ns() & 0xffffffff)
    call = (u32(xid) + u32(0) + u32(2) + u32(program) + u32(version) +
            u32(procedure) + u32(0) + u32(0) + u32(0) + u32(0) + args)
    socktype = socket.SOCK_DGRAM if transport == "udp" else socket.SOCK_STREAM
    result = {"endpoint": "%s:%d" % (host, port), "transport": transport,
              "program": program, "version": version, "procedure": procedure,
              "xid": xid}
    try:
        with socket.socket(socket.AF_INET, socktype) as s:
            s.settimeout(TIMEOUT)
            if transport == "udp":
                s.sendto(call, (host, port))
                data, peer = s.recvfrom(65535)
                result["peer"] = "%s:%d" % peer
            else:
                s.connect((host, port))
                s.sendall(u32(0x80000000 | len(call)) + call)
                chunks = []
                while True:
                    mark = recv_exact(s, 4)
                    word = struct.unpack("!I", mark)[0]
                    size = word & 0x7fffffff
                    chunks.append(recv_exact(s, size))
                    if word & 0x80000000:
                        break
                data = b"".join(chunks)
            result["response_bytes"] = len(data)
            result["raw_response_hex"] = data.hex()
            d = XDR(data)
            reply_xid = d.u32()
            msg_type = d.u32()
            result["reply_xid"] = reply_xid
            if reply_xid != xid or msg_type != 1:
                result["status"] = "unexpected_rpc_reply"
                return result, None
            reply_stat = d.u32()
            result["reply_status"] = reply_stat
            if reply_stat != 0:
                result["status"] = "rpc_denied"
                return result, None
            verifier_flavor = d.u32()
            verifier = d.opaque()
            accept_stat = d.u32()
            result["verifier_flavor"] = verifier_flavor
            result["accept_status"] = accept_stat
            if accept_stat != 0:
                result["status"] = "rpc_program_or_procedure_error"
                return result, None
            result["status"] = "response_decoded"
            return result, data[d.p:]
    except Exception as e:
        result["status"] = "no_decoded_response"
        result["error"] = "%s: %s" % (type(e).__name__, str(e))
        return result, None

def recv_exact(sock, n):
    parts = []
    left = n
    while left:
        b = sock.recv(left)
        if not b:
            raise EOFError("connection closed while reading RPC record")
        parts.append(b)
        left -= len(b)
    return b"".join(parts)

def parse_pmap_dump(payload):
    d = XDR(payload)
    mappings = []
    while d.u32():
        mappings.append({"program": d.u32(), "version": d.u32(),
                         "protocol": d.u32(), "port": d.u32()})
    return mappings

def parse_exports(payload):
    d = XDR(payload)
    exports = []
    while d.u32():
        path = d.string()
        groups = []
        while d.u32():
            groups.append(d.string())
        exports.append({"path": path, "groups": groups})
    return exports

def parse_readdir(payload):
    d = XDR(payload)
    status = d.u32()
    out = {"nfs_status": status, "entries": []}
    if status:
        return out
    verifier = d.take(8)
    out["cookieverf_hex"] = verifier.hex()
    while d.u32():
        out["entries"].append({"fileid": d.u64(), "name": d.string(), "cookie": d.u64()})
    out["eof"] = bool(d.u32())
    return out

def parse_mount_result(payload, version):
    d = XDR(payload)
    status = d.u32()
    out = {"mount_status": status}
    if status:
        return out, None
    if version >= 3:
        fh = d.opaque()
        count = d.u32()
        flavors = [d.u32() for _ in range(count)]
    else:
        fh = d.take(32)
        flavors = []
    out["filehandle_hex"] = fh.hex()
    out["auth_flavors"] = flavors
    return out, fh

def parse_nfs_attr(payload):
    d = XDR(payload)
    status = d.u32()
    if status:
        return {"nfs_status": status}
    if not d.u32():
        return {"nfs_status": 0, "attributes": None}
    typ = d.u32()
    mode = d.u32()
    nlink = d.u32()
    uid = d.u32()
    gid = d.u32()
    size = d.u64()
    used = d.u64()
    rdev_major = d.u32()
    rdev_minor = d.u32()
    fsid = d.u64()
    fileid = d.u64()
    return {"nfs_status": 0, "attributes": {"type": typ, "mode": mode,
            "nlink": nlink, "uid": uid, "gid": gid, "size": size,
            "used": used, "rdev": [rdev_major, rdev_minor],
            "fsid": fsid, "fileid": fileid}}

def nfs_call(host, port, transport, version, procedure, args):
    return rpc_call(host, port, transport, 100003, version, procedure, args)

def main():
    events = []
    mappings_by_host = {}
    for host in HOSTS:
        if host == EXCLUDED:
            continue
        for transport in ("udp", "tcp"):
            event, payload = rpc_call(host, 111, transport, 100000, 2, 4)
            if payload is not None:
                try:
                    maps = parse_pmap_dump(payload)
                    event["mappings"] = maps
                    mappings_by_host.setdefault(host, []).extend(maps)
                except Exception as e:
                    event["parse_error"] = "%s: %s" % (type(e).__name__, str(e))
            events.append(event)

    for host, maps in mappings_by_host.items():
        unique = {}
        for m in maps:
            if m["port"] and m["protocol"] in (6, 17):
                key = (m["program"], m["version"], m["protocol"], m["port"])
                unique[key] = m
        for (program, version, proto, port), m in unique.items():
            transport = "tcp" if proto == 6 else "udp"
            if program == 100024 and version == 1:
                # STAT is a read-only status query; the argument is an observed in-scope host.
                ev, _ = rpc_call(host, port, transport, program, version, 1,
                                 xdr_string(host))
                ev["interaction"] = "status STAT (read-only)"
                events.append(ev)
            elif program == 100005 and version in (1, 3):
                # EXPORT is read-only and returns only server-advertised paths/groups.
                ev, payload = rpc_call(host, port, transport, program, version, 5)
                ev["interaction"] = "MOUNT EXPORT (read-only)"
                exports = []
                if payload is not None:
                    try:
                        exports = parse_exports(payload)
                        ev["exports"] = exports
                    except Exception as e:
                        ev["parse_error"] = "%s: %s" % (type(e).__name__, str(e))
                events.append(ev)
                mount_version = 3 if version == 3 else 1
                nfs_versions = [x[1] for x in unique if x[0] == 100003 and x[1] == 3]
                nfs_map = next((x for x in unique if x[0] == 100003 and x[1] == 3), None)
                for export in exports:
                    mnt, mnt_payload = rpc_call(host, port, transport, 100005,
                                                mount_version, 1,
                                                xdr_string(export["path"]))
                    mnt["interaction"] = "MOUNT MNT read-only"
                    mnt["export_path"] = export["path"]
                    fh = None
                    if mnt_payload is not None:
                        try:
                            parsed, fh = parse_mount_result(mnt_payload, mount_version)
                            mnt.update(parsed)
                        except Exception as e:
                            mnt["parse_error"] = "%s: %s" % (type(e).__name__, str(e))
                    events.append(mnt)
                    if fh is None or nfs_map is None:
                        continue
                    nfs_port = nfs_map[3]
                    nfs_transport = "tcp" if nfs_map[2] == 6 else "udp"
                    attr_ev, attr_payload = nfs_call(host, nfs_port, nfs_transport, 3, 1,
                                                     opaque(fh))
                    attr_ev["interaction"] = "NFSv3 GETATTR on successfully mounted export"
                    attr = None
                    if attr_payload is not None:
                        try:
                            attr = parse_nfs_attr(attr_payload)
                            attr_ev["attributes"] = attr
                        except Exception as e:
                            attr_ev["parse_error"] = "%s: %s" % (type(e).__name__, str(e))
                    events.append(attr_ev)
                    if not attr or attr.get("nfs_status") != 0 or not attr.get("attributes") or attr["attributes"]["type"] != 2:
                        continue
                    rd_args = opaque(fh) + u64(0) + (b"\0" * 8) + u32(65536)
                    rd_ev, rd_payload = nfs_call(host, nfs_port, nfs_transport, 3, 16, rd_args)
                    rd_ev["interaction"] = "NFSv3 READDIR of accessible export root"
                    entries = []
                    if rd_payload is not None:
                        try:
                            rd = parse_readdir(rd_payload)
                            rd_ev.update(rd)
                            entries = rd["entries"] if rd["nfs_status"] == 0 else []
                        except Exception as e:
                            rd_ev["parse_error"] = "%s: %s" % (type(e).__name__, str(e))
                    events.append(rd_ev)
                    # Inspect accessible regular files directly within the exported root.
                    for entry in entries:
                        name = entry["name"]
                        if name in (".", ".."):
                            continue
                        look_args = opaque(fh) + xdr_string(name)
                        look_ev, look_payload = nfs_call(host, nfs_port, nfs_transport, 3, 3, look_args)
                        look_ev["interaction"] = "NFSv3 LOOKUP in accessible export root"
                        look_ev["name"] = name
                        objfh = None
                        objattr = None
                        if look_payload is not None:
                            try:
                                ld = XDR(look_payload)
                                status = ld.u32()
                                look_ev["nfs_status"] = status
                                if status == 0:
                                    objfh = ld.opaque()
                                    hasattr = ld.u32()
                                    if hasattr:
                                        rest = look_payload[ld.p:]
                                        objattr = parse_nfs_attr(u32(0) + u32(1) + rest)
                                        look_ev["attributes"] = objattr
                            except Exception as e:
                                look_ev["parse_error"] = "%s: %s" % (type(e).__name__, str(e))
                        events.append(look_ev)
                        if not objfh or not objattr or not objattr.get("attributes") or objattr["attributes"]["type"] != 1:
                            continue
                        size = objattr["attributes"]["size"]
                        chunks = []
                        offset = 0
                        read_error = None
                        while offset < size:
                            count = min(65536, size - offset)
                            args = opaque(objfh) + u64(offset) + u32(count)
                            read_ev, read_payload = nfs_call(host, nfs_port, nfs_transport, 3, 6, args)
                            read_ev["interaction"] = "NFSv3 READ of accessible regular file"
                            read_ev["path"] = export["path"] + "/" + name
                            if read_payload is None:
                                events.append(read_ev)
                                read_error = read_ev.get("error", read_ev.get("status"))
                                break
                            try:
                                rd = XDR(read_payload)
                                status = rd.u32()
                                read_ev["nfs_status"] = status
                                if status:
                                    events.append(read_ev)
                                    read_error = "NFS status %d" % status
                                    break
                                hasattr = rd.u32()
                                if hasattr:
                                    read_ev["attributes"] = parse_nfs_attr(u32(0) + u32(1) + read_payload[rd.p:])
                                    # Skip the fixed NFSv3 fattr3 structure (84 bytes).
                                    rd.take(84)
                                got = rd.u32()
                                eof = bool(rd.u32())
                                data = rd.opaque()
                                chunks.append(data)
                                read_ev.update({"count": got, "eof": eof, "data_bytes": len(data),
                                                "data_hex": data.hex()})
                                events.append(read_ev)
                                if not data:
                                    break
                                offset += len(data)
                                if eof:
                                    break
                            except Exception as e:
                                read_ev["parse_error"] = "%s: %s" % (type(e).__name__, str(e))
                                events.append(read_ev)
                                read_error = read_ev["parse_error"]
                                break
                        if chunks:
                            content = b"".join(chunks)
                            events.append({"interaction": "assembled directly observed file content",
                                           "host": host, "path": export["path"] + "/" + name,
                                           "bytes": len(content), "content_utf8": content.decode("utf-8", "replace"),
                                           "content_hex": content.hex(), "read_error": read_error})

    print(json.dumps({"scope_hosts_examined_for_portmapper": HOSTS,
                      "excluded_host": EXCLUDED,
                      "method": "read-only ONC RPC portmapper DUMP, status STAT, MOUNT EXPORT/MNT, and NFSv3 GETATTR/READDIR/LOOKUP/READ where mapped and accessible",
                      "events": events}, sort_keys=True))

if __name__ == "__main__":
    main()

