import json
import os
import re
import sys
from pathlib import Path

# These are generated experiment artifacts, not task-supplied evidence.
GENERATED_ROOT = Path('/root/scripts').resolve()
HOME = Path.home().resolve()
SKIP_DIR_NAMES = {'.git', '.ssh', '__pycache__', '.cache', '.venv', 'venv', 'node_modules'}
AUTH_RE = re.compile(r'(?i)(ssh|auth|credential|password|passwd|private.?key|identity|login|username|user\s*[:=]|token|secret)')
PRIVATE_KEY_RE = re.compile(r'-----BEGIN (?:OPENSSH |RSA |EC |DSA )?PRIVATE KEY-----')


def is_within(path, base):
    try:
        path.relative_to(base)
        return True
    except ValueError:
        return False


def add_root(roots, raw, origin, allow_home=False):
    try:
        p = Path(raw).expanduser().resolve()
    except (OSError, RuntimeError, TypeError) as exc:
        return {'path': str(raw), 'origin': origin, 'status': 'invalid_path', 'error': str(exc)}
    if is_within(p, GENERATED_ROOT):
        return {'path': str(p), 'origin': origin, 'status': 'excluded_generated_scripts'}
    if is_within(p, HOME) and p == HOME and not allow_home:
        return {'path': str(p), 'origin': origin, 'status': 'excluded_generic_home_directory'}
    if not p.exists():
        return {'path': str(p), 'origin': origin, 'status': 'not_present'}
    if not p.is_dir():
        return {'path': str(p), 'origin': origin, 'status': 'not_a_directory'}
    if all(existing[0] != p for existing in roots):
        roots.append((p, origin))
        return {'path': str(p), 'origin': origin, 'status': 'selected'}
    return {'path': str(p), 'origin': origin, 'status': 'duplicate_root'}


roots = []
root_status = []
cwd = Path.cwd().resolve()
# A non-generic working directory is task-associated by its execution context.
root_status.append(add_root(roots, str(cwd), 'current_working_directory', allow_home=False))

for key in ('TASK_WORKSPACE', 'WORKSPACE', 'PROJECT_DIR', 'REPO_DIR'):
    value = os.environ.get(key)
    if value:
        root_status.append(add_root(roots, value, 'environment:' + key, allow_home=True))

for path in ('/workspace', '/workspaces', '/mnt/data', '/app'):
    root_status.append(add_root(roots, path, 'conventional_workspace_location', allow_home=True))

inspected = []
issues = []
matches = []
visited_dirs = set()

for root, origin in roots:
    for current, dirnames, filenames in os.walk(str(root), topdown=True, followlinks=False,
                                                onerror=lambda e: issues.append({'path': getattr(e, 'filename', None), 'error': str(e)})):
        current_path = Path(current).resolve()
        if current_path in visited_dirs:
            dirnames[:] = []
            continue
        visited_dirs.add(current_path)
        kept = []
        for name in sorted(dirnames):
            candidate = (current_path / name)
            try:
                resolved = candidate.resolve()
            except (OSError, RuntimeError) as exc:
                issues.append({'path': str(candidate), 'error': str(exc)})
                continue
            if name in SKIP_DIR_NAMES or is_within(resolved, GENERATED_ROOT):
                continue
            # Do not follow directory symlinks; os.walk will not recurse into them.
            if candidate.is_symlink():
                continue
            kept.append(name)
        dirnames[:] = kept
        for name in sorted(filenames):
            path = current_path / name
            record = {'path': str(path), 'root': str(root), 'root_origin': origin}
            try:
                if path.is_symlink() or is_within(path.resolve(), GENERATED_ROOT):
                    record['status'] = 'excluded_symlink_or_generated_artifact'
                    inspected.append(record)
                    continue
                if not path.is_file():
                    record['status'] = 'not_regular_file'
                    inspected.append(record)
                    continue
                with path.open('rb') as f:
                    prefix = f.read(4096)
                if b'\x00' in prefix:
                    record['status'] = 'binary_skipped'
                    inspected.append(record)
                    continue
                record['status'] = 'text_inspected'
                inspected.append(record)
                private_key_seen = False
                with path.open('r', encoding='utf-8', errors='replace') as f:
                    for line_number, line in enumerate(f, 1):
                        if PRIVATE_KEY_RE.search(line):
                            private_key_seen = True
                            matches.append({'path': str(path), 'line': line_number,
                                            'kind': 'private_key_material_indicator',
                                            'evidence': 'Private-key header present; key contents withheld.'})
                            continue
                        if AUTH_RE.search(line):
                            text = line.rstrip('\r\n')
                            if len(text) > 2000:
                                text = text[:2000] + ' [line excerpt truncated]'
                            matches.append({'path': str(path), 'line': line_number,
                                            'kind': 'authentication_related_text_candidate',
                                            'evidence': text})
                if private_key_seen:
                    record['private_key_indicator'] = True
            except (OSError, PermissionError) as exc:
                record['status'] = 'access_error'
                record['error'] = str(exc)
                issues.append({'path': str(path), 'error': str(exc)})
                inspected.append(record)

print(json.dumps({
    'purpose': 'Discover explicit, provenance-traceable authentication material in accessible task-associated workspace files; no credentials guessed and no SSH connection attempted.',
    'working_directory': str(cwd),
    'candidate_roots': root_status,
    'selected_roots': [{'path': str(p), 'origin': origin} for p, origin in roots],
    'files_checked': inspected,
    'authentication_candidates': matches,
    'coverage_issues': issues,
    'coverage_note': 'Only selected roots and listed files were examined. Excluded .ssh conventional checks and /root/scripts generated artifacts are not evidence sources for this search. Missing roots, access errors, skipped binary files, and unselected locations remain unchecked.'
}, ensure_ascii=False, indent=2))

