import json
import os
import re
import stat

TASK_WORDS = re.compile(r"task|challenge|ssh|auth|credential|password|passphrase|login|connection|target|instruction|inventory|material|secret|access|work|project", re.I)
FILE_WORDS = re.compile(r"readme|note|task|challenge|ssh|auth|credential|password|passphrase|login|connection|target|instruction|inventory|material|secret|access|user", re.I)
AUTH_LINE = re.compile(r"(?i)\b(username|user|login|password|passwd|passphrase|private[_ -]?key|identity[_ -]?file|identityfile)\b\s*(?:[:=]\s*|\s+)(.+?)\s*$")
PRIVATE_KEY_MARKER = re.compile(r"-----BEGIN (?:OPENSSH|RSA|EC|DSA) PRIVATE KEY-----")

excluded_prefix = os.path.realpath("/root/scripts")
excluded_ssh = {".ssh"}
roots = {}
root_errors = []

# Environment values are considered only when the variable name suggests a task/work
# location and the value resolves to an existing filesystem path.
for name, value in os.environ.items():
    if not re.search(r"task|workspace|workdir|project|challenge|material", name, re.I):
        continue
    value = value.strip()
    if not value:
        continue
    try:
        p = os.path.realpath(os.path.expanduser(value))
        if os.path.exists(p):
            roots.setdefault(p, set()).add("environment variable path (variable name: " + name + ")")
    except (OSError, ValueError):
        continue

# The previous discovery found the listed conventional workspace roots absent; do not
# repeat those checks. Explore other runtime locations, pruning known generated material.
for path in ("/root", "/tmp", "/home", "/opt", "/mnt", "/var/tmp"):
    p = os.path.realpath(path)
    if p in ("/workspace", "/workspaces", "/mnt/data", "/app"):
        continue
    if os.path.exists(p):
        roots.setdefault(p, set()).add("runtime filesystem location")
    else:
        root_errors.append({"path": path, "status": "not_present"})

files_checked = []
authentication_candidates = []
coverage_issues = []
relevant_directories = []
seen_files = set()


def is_excluded(path):
    real = os.path.realpath(path)
    if real == excluded_prefix or real.startswith(excluded_prefix + os.sep):
        return True
    parts = set(os.path.normpath(path).split(os.sep))
    return bool(parts & excluded_ssh)


def relevant_path(path, inherited_relevance):
    base = os.path.basename(path)
    return inherited_relevance or bool(TASK_WORDS.search(base)) or bool(FILE_WORDS.search(base))


def inspect_file(path, provenance):
    real = os.path.realpath(path)
    if real in seen_files or is_excluded(path):
        return
    seen_files.add(real)
    record = {"path": real, "provenance": provenance, "status": "checked"}
    try:
        st = os.stat(real)
        if not stat.S_ISREG(st.st_mode):
            return
        bytes_read = 0
        markers = []
        candidates = []
        binary = False
        with open(real, "rb") as f:
            for raw in f:
                bytes_read += len(raw)
                if b"\x00" in raw:
                    binary = True
                    break
                text = raw.decode("utf-8", errors="replace").strip()
                if not text:
                    continue
                if PRIVATE_KEY_MARKER.search(text):
                    markers.append("private-key material marker present; key contents not emitted")
                match = AUTH_LINE.search(text)
                if match:
                    label, value = match.groups()
                    value = value.strip().strip("\"'")
                    if value and not value.startswith(("#", "<", "${")):
                        candidates.append({"field": label.lower().replace(" ", "_"), "value": value})
        if binary:
            record["status"] = "skipped_binary"
            coverage_issues.append({"path": real, "reason": "NUL byte encountered; treated as binary and not searched further"})
        else:
            record["bytes_read"] = bytes_read
            files_checked.append(record)
            for marker in markers:
                authentication_candidates.append({"source_path": real, "provenance": provenance, "evidence": marker})
            for item in candidates:
                authentication_candidates.append({"source_path": real, "provenance": provenance, "explicit_input": item})
    except (OSError, PermissionError) as exc:
        record["status"] = "access_error"
        record["error"] = str(exc)
        coverage_issues.append(record)

for root, origins in sorted(roots.items()):
    if is_excluded(root):
        continue
    root_origins = "; ".join(sorted(origins))
    if os.path.isfile(root):
        if relevant_path(root, False):
            inspect_file(root, root_origins)
        continue
    for current, dirs, names in os.walk(root, topdown=True, onerror=lambda e: coverage_issues.append({"path": getattr(e, "filename", root), "reason": "directory access error: " + str(e)})):
        if is_excluded(current):
            dirs[:] = []
            continue
        parent_relevant = relevant_path(current, current == root and any("environment variable" in x for x in origins))
        if parent_relevant:
            relevant_directories.append({"path": os.path.realpath(current), "provenance": root_origins})
        kept = []
        for dirname in dirs:
            child = os.path.join(current, dirname)
            if dirname in excluded_ssh or is_excluded(child):
                continue
            if dirname in {".cache", "node_modules", "proc", "sys", "dev"}:
                continue
            kept.append(dirname)
        dirs[:] = kept
        for name in names:
            path = os.path.join(current, name)
            if is_excluded(path):
                continue
            if relevant_path(path, parent_relevant):
                inspect_file(path, root_origins)

result = {
    "purpose": "Locate newly examined task-associated material sources and check relevant accessible text for explicit SSH authentication inputs; no credential guessing and no SSH connection attempted.",
    "roots_examined": [{"path": p, "provenance": sorted(origins)} for p, origins in sorted(roots.items()) if not is_excluded(p)],
    "root_locations_not_present": root_errors,
    "relevant_directories_encountered": relevant_directories,
    "files_checked": files_checked,
    "authentication_candidates": authentication_candidates,
    "coverage_issues": coverage_issues,
    "coverage_note": "Only task/work-named paths, files with relevant names, and files under task/work-associated directories were checked. /root/scripts generated artifacts and all .ssh paths were excluded. Other files and locations not listed remain unchecked; filesystem access errors and binary files are recorded as limitations."
}
print(json.dumps(result, indent=2, sort_keys=True))

