import json
import os
import re
import sys
from pathlib import Path

ARTIFACT = "llm_inputs/3e10011685931b72dcf61c0cf88407a8c729f509f68948f5aa10019297a5a62b.json"
SCOPE = __import__("ipaddress").ip_network("192.168.0.0/16")
SKIP_IP = "192.168.122.1"
IP_RE = re.compile(r"(?<![0-9.])(?:[0-9]{1,3}\.){3}[0-9]{1,3}(?![0-9.])")


def candidate_paths():
    seen = set()
    cwd = Path.cwd()
    bases = [cwd, *list(cwd.parents), Path("/root"), Path("/workspace"),
             Path("/tmp"), Path("/mnt/data"), Path("/app")]
    for base in bases:
        p = base / ARTIFACT
        key = str(p)
        if key not in seen:
            seen.add(key)
            yield p


def stringify(value):
    if isinstance(value, str):
        return value
    try:
        return json.dumps(value, ensure_ascii=False, sort_keys=True)
    except Exception:
        return repr(value)


def is_rpc_record(obj):
    node_id = stringify(obj.get("node_id", "")).lower()
    goal = stringify(obj.get("goal", "")).lower()
    return "rpc" in node_id or ("rpc" in goal and any(k in obj for k in ("execution_result", "stdout", "observation")))


def collect_records(value, path="$", found=None):
    if found is None:
        found = []
    if isinstance(value, dict):
        if is_rpc_record(value):
            found.append((path, value))
        for key, child in value.items():
            collect_records(child, path + "[" + json.dumps(str(key)) + "]", found)
    elif isinstance(value, list):
        for index, child in enumerate(value):
            collect_records(child, path + "[" + str(index) + "]", found)
    return found


def extract_candidate_evidence(record, source_ref):
    text_parts = []
    for key in ("goal", "command", "stdout", "stderr", "observation", "expected_observation"):
        if key in record:
            text_parts.append(stringify(record[key]))
    result = record.get("execution_result")
    if isinstance(result, dict):
        for key in ("command", "stdout", "stderr"):
            if key in result:
                text_parts.append(stringify(result[key]))
        structured = result.get("structured_output")
        if structured is not None:
            text_parts.append(stringify(structured))
    text = "\n".join(text_parts)
    ips = []
    for match in IP_RE.finditer(text):
        ip = match.group(0)
        try:
            if ip != SKIP_IP and __import__("ipaddress").ip_address(ip) in SCOPE and ip not in ips:
                ips.append(ip)
        except ValueError:
            pass
    # Keep candidate port tokens explicitly associated with their source text;
    # do not infer that a port label alone establishes a service.
    port_candidates = []
    patterns = [
        re.compile(r"(?i)\b(?:port|ports)\s*[:=]?\s*(\d{1,5})\b"),
        re.compile(r"(?<!\d)(\d{1,5})/(?:tcp|udp)\b", re.I),
        re.compile(r"(?<![\d.])(?:192\.168\.(?:\d{1,3})\.(?:\d{1,3})):(\d{1,5})\b"),
    ]
    for pattern in patterns:
        for match in pattern.finditer(text):
            token = match.group(1)
            try:
                number = int(token)
                if 1 <= number <= 65535 and number not in port_candidates:
                    port_candidates.append(number)
            except ValueError:
                pass
    return {"source_ref": source_ref, "in_scope_addresses": ips,
            "port_number_candidates": port_candidates}


def main():
    attempts = []
    archive_path = None
    for path in candidate_paths():
        attempts.append(str(path))
        try:
            if path.is_file():
                archive_path = path
                break
        except OSError:
            continue
    if archive_path is None:
        print(json.dumps({"status": "archive_not_found", "artifact": ARTIFACT,
                          "paths_checked": attempts,
                          "limitation": "The exact archived input was not accessible at the checked paths; the partial preview cannot establish complete RPC endpoint findings."}, ensure_ascii=False))
        return
    try:
        with archive_path.open("r", encoding="utf-8") as handle:
            archive = json.load(handle)
    except Exception as exc:
        print(json.dumps({"status": "archive_read_or_parse_error", "archive_path": str(archive_path),
                          "error": str(exc), "limitation": "Full prior-observation material was not successfully reviewed."}, ensure_ascii=False))
        return

    material = archive
    selector = '$["prior_observations"]'
    if isinstance(archive, dict) and "prior_observations" in archive:
        material = archive["prior_observations"]
    records = collect_records(material, selector)
    output_records = []
    extracted = []
    seen = set()
    for source_path, record in records:
        node_id = record.get("node_id")
        observed_at = record.get("observed_at")
        result = record.get("execution_result")
        key = (stringify(node_id), stringify(observed_at), stringify(result if result is not None else record.get("stdout")))
        if key in seen:
            continue
        seen.add(key)
        selected = {"source_ref": source_path, "node_id": node_id,
                    "observed_at": observed_at, "goal": record.get("goal")}
        if isinstance(result, dict):
            selected["execution_result"] = {k: result[k] for k in
                ("status", "exit_code", "command", "stdout", "stderr", "duration_seconds", "structured_output") if k in result}
        else:
            for k in ("command", "stdout", "stderr", "structured_output", "observation"):
                if k in record:
                    selected[k] = record[k]
        output_records.append(selected)
        extracted.append(extract_candidate_evidence(record, source_path))

    print(json.dumps({"status": "reviewed", "archive_path": str(archive_path),
                      "material_selector": selector,
                      "rpc_record_count": len(output_records),
                      "rpc_observation_records": output_records,
                      "address_and_port_candidates": extracted,
                      "interpretation": "Candidates are extracted only from source-record text and retain source references. A candidate port or address is not, by itself, proof of a confirmed service/endpoint. The ignored host 192.168.122.1 is omitted. No absence claim is made for unrepresented, missing, or truncated observations."}, ensure_ascii=False))


if __name__ == "__main__":
    main()

