import json
import socket
import struct
import time

HOST = "192.168.0.1"
RPCB_PORT = 111
TIMEOUT = 2.0


def u32(value):
    return struct.pack("!I", value & 0xffffffff)


def xdr_string(value):
    data = value.encode("ascii")
    return u32(len(data)) + data + b"\x00" * ((-len(data)) % 4)


def make_call(program, version, procedure, args=b""):
    xid = int.from_bytes(__import__("os").urandom(4), "big")
    body = b"".join((u32(xid), u32(0), u32(2), u32(program), u32(version),
                     u32(procedure), u32(0), u32(0), u32(0), u32(0), args))
    return xid, body


def read_exact(sock, count):
    chunks = []
    remaining = count
    while remaining:
        part = sock.recv(remaining)
        if not part:
            raise ConnectionError("peer closed before the complete RPC record arrived")
        chunks.append(part)
        remaining -= len(part)
    return b"".join(chunks)


def recv_tcp_record(sock):
    pieces = []
    while True:
        marker = struct.unpack("!I", read_exact(sock, 4))[0]
        last = bool(marker & 0x80000000)
        size = marker & 0x7fffffff
        pieces.append(read_exact(sock, size))
        if last:
            return b"".join(pieces)


def parse_reply(data, expected_xid):
    if len(data) < 12:
        raise ValueError("short RPC reply: %d bytes" % len(data))
    xid, msg_type, reply_stat = struct.unpack_from("!III", data, 0)
    result = {"xid": xid, "message_type": msg_type, "reply_status": reply_stat,
              "response_hex": data.hex()}
    if xid != expected_xid:
        raise ValueError("RPC XID mismatch: expected %u, received %u" % (expected_xid, xid))
    if msg_type != 1:
        raise ValueError("RPC message is not a REPLY")
    if reply_stat != 0:
        result["status"] = "rpc_denied"
        if len(data) >= 16:
            result["reject_status"] = struct.unpack_from("!I", data, 12)[0]
        return result, b""
    if len(data) < 20:
        raise ValueError("short accepted RPC reply")
    flavor, auth_len = struct.unpack_from("!II", data, 12)
    pos = 20 + auth_len + ((-auth_len) % 4)
    if len(data) < pos + 4:
        raise ValueError("truncated RPC verifier or accept status")
    accept_status = struct.unpack_from("!I", data, pos)[0]
    result.update({"status": "response_received", "verifier_flavor": flavor,
                   "accept_status": accept_status})
    return result, data[pos + 4:] if accept_status == 0 else b""


def rpc_call(transport, port, program, version, procedure, args=b""):
    xid, call = make_call(program, version, procedure, args)
    started = time.monotonic()
    with socket.socket(socket.AF_INET, socket.SOCK_STREAM if transport == "tcp" else socket.SOCK_DGRAM) as sock:
        sock.settimeout(TIMEOUT)
        if transport == "tcp":
            sock.connect((HOST, port))
            sock.sendall(u32(0x80000000 | len(call)) + call)
            raw = recv_tcp_record(sock)
        else:
            sock.sendto(call, (HOST, port))
            raw, _ = sock.recvfrom(65535)
    parsed, payload = parse_reply(raw, xid)
    parsed.update({"target": HOST, "transport": transport, "port": port,
                   "program": program, "version": version, "procedure": procedure,
                   "duration_seconds": round(time.monotonic() - started, 4)})
    return parsed, payload


def parse_export_list(payload):
    pos = 0
    exports = []

    def get_bool():
        nonlocal pos
        if pos + 4 > len(payload):
            raise ValueError("truncated export-list boolean")
        value = struct.unpack_from("!I", payload, pos)[0]
        pos += 4
        if value not in (0, 1):
            raise ValueError("invalid XDR boolean %d" % value)
        return bool(value)

    def get_string():
        nonlocal pos
        if pos + 4 > len(payload):
            raise ValueError("truncated XDR string length")
        size = struct.unpack_from("!I", payload, pos)[0]
        pos += 4
        end = pos + size
        if end > len(payload):
            raise ValueError("truncated XDR string")
        value = payload[pos:end].decode("utf-8", "replace")
        pos = end + ((-size) % 4)
        if pos > len(payload):
            raise ValueError("truncated XDR string padding")
        return value

    while get_bool():
        path = get_string()
        groups = []
        while get_bool():
            groups.append(get_string())
        exports.append({"path": path, "groups": groups})
    return exports, pos, len(payload)


def attempt(label, transport, port, program, version, procedure, args=b""):
    item = {"check": label, "transport": transport, "port": port,
            "program": program, "version": version, "procedure": procedure}
    try:
        reply, payload = rpc_call(transport, port, program, version, procedure, args)
        item["rpc_response"] = reply
        if reply.get("accept_status") == 0:
            item["result_payload_hex"] = payload.hex()
        return item, payload, reply
    except Exception as exc:
        item["status"] = "error_or_no_response"
        item["error"] = "%s: %s" % (type(exc).__name__, exc)
        return item, b"", None


def main():
    report = {
        "scope": {"host": HOST},
        "basis": "Prior rpcbind DUMP on 192.168.0.1:111/TCP reported program 100024 v1 at TCP/41227 and UDP/54755.",
        "read_only_checks": [],
        "mapping_queries": [],
        "discovered_mount_mappings": [],
        "discovered_nfs_mappings": [],
        "export_checks": [],
        "coverage": {
            "statd_null": ["192.168.0.1:41227/TCP", "192.168.0.1:54755/UDP"],
            "rpcbind_getport": "rpcbind v2 GETPORT on 192.168.0.1:111/TCP; mount program 100005 versions 1-3 and NFS program 100003 versions 2-4 over TCP and UDP",
            "export_procedure": "mount protocol EXPORT procedure 5, only for mappings returned with nonzero port",
            "limitations": []
        }
    }

    # Program 100024 is statd; procedure 0 is the read-only RPC NULL procedure.
    for transport, port in (("tcp", 41227), ("udp", 54755)):
        item, _, _ = attempt("statd_NULL", transport, port, 100024, 1, 0)
        report["read_only_checks"].append(item)

    # rpcbind v2 GETPORT (procedure 3): program, version, IP protocol, requested port 0.
    candidates = [(100005, version, "mount") for version in (1, 2, 3)]
    candidates += [(100003, version, "nfs") for version in (2, 3, 4)]
    for program, version, kind in candidates:
        for transport, protocol_number in (("tcp", 6), ("udp", 17)):
            args = u32(program) + u32(version) + u32(protocol_number) + u32(0)
            item, payload, reply = attempt("rpcbind_GETPORT_" + kind, "tcp", RPCB_PORT,
                                           100000, 2, 3, args)
            mapping = {"program": program, "version": version, "service": kind,
                       "transport": transport}
            if reply is not None and reply.get("accept_status") == 0 and len(payload) >= 4:
                port = struct.unpack_from("!I", payload, 0)[0]
                mapping["port"] = port
                mapping["status"] = "mapped" if port else "no_mapping_returned"
                if port:
                    destination = report["discovered_mount_mappings"] if kind == "mount" else report["discovered_nfs_mappings"]
                    destination.append(mapping)
            else:
                mapping["status"] = "no_decodable_successful_reply"
            item.update({"queried_program": program, "queried_version": version,
                         "queried_transport_protocol_number": protocol_number,
                         "mapping_result": mapping})
            report["mapping_queries"].append(item)

    # A successful mapping justifies a protocol NULL check at that reported endpoint.
    for kind, mappings in (("mount", report["discovered_mount_mappings"]),
                           ("nfs", report["discovered_nfs_mappings"])):
        program = 100005 if kind == "mount" else 100003
        for mapping in mappings:
            check, _, _ = attempt(kind + "_NULL", mapping["transport"], mapping["port"],
                                  program, mapping["version"], 0)
            report["read_only_checks"].append(check)

    # MOUNT EXPORT is a read-only enumeration; call it only at discovered mountd endpoints.
    for mapping in report["discovered_mount_mappings"]:
        item, payload, reply = attempt("mount_EXPORT", mapping["transport"], mapping["port"],
                                       100005, mapping["version"], 5)
        if reply is not None and reply.get("accept_status") == 0:
            try:
                exports, consumed, payload_size = parse_export_list(payload)
                item["exports"] = exports
                item["xdr_parse"] = {"status": "parsed", "bytes_consumed": consumed,
                                     "payload_bytes": payload_size}
            except Exception as exc:
                item["xdr_parse"] = {"status": "failed", "error": "%s: %s" % (type(exc).__name__, exc)}
        report["export_checks"].append(item)

    if not report["discovered_mount_mappings"]:
        report["coverage"]["limitations"].append(
            "No mountd mapping with a nonzero port was returned by the attempted rpcbind v2 GETPORT queries; no EXPORT call was therefore made. This does not establish that no exports exist or rule out other RPC paths.")
    if not report["discovered_nfs_mappings"]:
        report["coverage"]["limitations"].append(
            "No NFS mapping with a nonzero port was returned by the attempted rpcbind v2 GETPORT queries; this is limited to versions 2-4 and TCP/UDP checked.")
    print(json.dumps(report, sort_keys=True))


if __name__ == "__main__":
    main()

