import hashlib
import json
import os
import shutil
import sys
from pathlib import Path

ARTIFACT = "llm_inputs/d7f23c7101dc2bd5fb1c529fe0cac26506f164acf967f85c5919ccd27036942e.json"
EXPECTED_SHA256 = "d7f23c7101dc2bd5fb1c529fe0cac26506f164acf967f85c5919ccd27036942e"
RPC_TERMS = ("rpc", "mount", "nfs", "portmap", "showmount")


def candidate_files():
    rel = Path(ARTIFACT)
    roots = []
    for value in (os.getcwd(), os.environ.get("PWD"), "/root", "/tmp", "/workspace", "/app", "/mnt/data"):
        if value:
            p = Path(value)
            if p not in roots:
                roots.append(p)
    seen = set()
    for root in roots:
        for base in (root / rel, root / rel.name):
            try:
                resolved = base.resolve()
            except OSError:
                resolved = base
            key = str(resolved)
            if key not in seen:
                seen.add(key)
                yield base
        # The artifact may be staged below a workspace directory. Search only
        # for this exact, supplied filename, without reading other files.
        try:
            for current, dirs, files in os.walk(root):
                dirs[:] = [d for d in dirs if d not in {".git", "proc", "sys", "dev", "node_modules", "__pycache__"}]
                if rel.name in files:
                    p = Path(current) / rel.name
                    key = str(p.resolve())
                    if key not in seen:
                        seen.add(key)
                        yield p
        except (OSError, PermissionError):
            continue


def rpc_history(obj):
    """Return complete history records whose supplied content concerns RPC/NFS."""
    results = []
    seen = set()

    def visit(value, path="$", in_history=False):
        if isinstance(value, dict):
            hist = value.get("history")
            if isinstance(hist, list):
                for i, entry in enumerate(hist):
                    if isinstance(entry, dict):
                        text = json.dumps(entry, ensure_ascii=False, sort_keys=True).lower()
                        if any(term in text for term in RPC_TERMS):
                            marker = (entry.get("node_id"), entry.get("observed_at"), i)
                            if marker not in seen:
                                seen.add(marker)
                                results.append({"source_path": f"{path}.history[{i}]", "record": entry})
            for key, child in value.items():
                if key != "history":
                    visit(child, f"{path}[{json.dumps(str(key))}]")
        elif isinstance(value, list):
            for i, child in enumerate(value):
                visit(child, f"{path}[{i}]")

    visit(obj)
    return results


def inspect_artifact():
    checked = []
    for path in candidate_files():
        item = {"path": str(path), "exists": False}
        try:
            if not path.is_file():
                checked.append(item)
                continue
            item["exists"] = True
            raw = path.read_bytes()
            digest = hashlib.sha256(raw).hexdigest()
            item["sha256"] = digest
            item["hash_matches_supplied_artifact"] = digest == EXPECTED_SHA256
            if digest != EXPECTED_SHA256:
                item["note"] = "Filename matched, but content hash did not; not treated as the supplied original input."
                checked.append(item)
                continue
            data = json.loads(raw.decode("utf-8"))
            item["json_parse"] = "success"
            prior = data.get("prior_observations") if isinstance(data, dict) else None
            item["prior_observations_type"] = type(prior).__name__
            records = rpc_history({"prior_observations": prior}) if prior is not None else []
            item["rpc_relevant_history_record_count"] = len(records)
            item["rpc_relevant_history_records"] = records
            return {"checked_candidates": checked + [item], "artifact_recovered": True}
        except (OSError, UnicodeError, json.JSONDecodeError) as exc:
            item["error"] = f"{type(exc).__name__}: {exc}"
        checked.append(item)
    return {"checked_candidates": checked, "artifact_recovered": False,
            "limitation": "The exact original artifact was not recovered from the checked candidate locations; this does not establish that it is absent elsewhere."}


def local_capabilities():
    executables = {}
    for name in ("rpcinfo", "showmount", "mount.nfs", "mount", "nfsstat", "nmap"):
        found = shutil.which(name)
        executables[name] = {"available_on_PATH": found is not None, "path": found}
    script_names = ("nfs-showmount.nse", "nfs-ls.nse", "nfs-statfs.nse", "rpcinfo.nse", "rpc-grind.nse")
    script_dirs = (
        Path("/usr/share/nmap/scripts"),
        Path("/usr/local/share/nmap/scripts"),
        Path("/usr/share/nmap"),
    )
    scripts = {}
    for name in script_names:
        locations = []
        for directory in script_dirs:
            candidate = directory / name
            try:
                if candidate.is_file():
                    locations.append(str(candidate))
            except OSError:
                pass
        scripts[name] = {"present_in_checked_locations": bool(locations), "paths": locations}
    return {
        "executables": executables,
        "nmap_nse_scripts": scripts,
        "checked_script_directories": [str(p) for p in script_dirs],
        "interpretation": "Presence is a local capability indication, not proof of endpoint reachability, permissions, or a successful protocol request. No credentials or endpoint addresses are supplied or inferred here."
    }


report = {
    "purpose": "Recover full prior RPC/NFS observations and check local protocol-request methods; no network activity performed.",
    "artifact_recovery": inspect_artifact(),
    "local_protocol_capabilities": local_capabilities(),
    "scope_note": "No endpoint was contacted, no credential was guessed, and 192.168.122.1 was not used or inferred."
}
json.dump(report, sys.stdout, ensure_ascii=False, indent=2)
sys.stdout.write("\n")

