import hashlib
import json
import os
import sys
from pathlib import Path

ARTIFACT = "a2a5e48a1fdde63454d814efaf0b4057c6784441e4dd1f26a8afc1818f9e9687.json"
EXPECTED_SHA256 = "a2a5e48a1fdde63454d814efaf0b4057c6784441e4dd1f26a8afc1818f9e9687"
SOURCE_KEY = "prior_observations"

roots = [
    Path.cwd(),
    Path("/root/scripts"), Path("/root"), Path("/tmp"),
    Path("/workspace"), Path("/app"), Path("/mnt/data"),
]
candidates = []
for root in roots:
    for relative in (Path("llm_inputs") / ARTIFACT, Path(ARTIFACT)):
        candidate = root / relative
        if candidate not in candidates:
            candidates.append(candidate)

existing = []
for path in candidates:
    try:
        if path.is_file():
            resolved = path.resolve()
            if resolved not in existing:
                existing.append(resolved)
    except OSError:
        pass

result = {
    "purpose": "Retrieve and review the exact archived prior-observations source; no network activity performed.",
    "supplied_artifact": "llm_inputs/" + ARTIFACT,
    "expected_sha256": EXPECTED_SHA256,
    "source_path": "$[\"prior_observations\"]",
    "candidate_paths_checked": [str(p) for p in candidates],
}

if not existing:
    result.update({
        "archive_recovered": False,
        "limitation": "The exact supplied artifact was not present at the checked candidate paths. This does not establish that it is absent elsewhere; no RPC endpoint or service details can be recovered from this execution.",
        "supported_alternative": "Provide or mount the exact original_input archive at its supplied llm_inputs path, then rerun this retrieval against that artifact.",
    })
    print(json.dumps(result, ensure_ascii=False, indent=2))
    sys.exit(0)

archive_path = existing[0]
try:
    raw = archive_path.read_bytes()
    actual_sha = hashlib.sha256(raw).hexdigest()
    document = json.loads(raw.decode("utf-8"))
except Exception as exc:
    result.update({
        "archive_recovered": True,
        "archive_path": str(archive_path),
        "read_or_parse_error": repr(exc),
        "limitation": "The exact artifact path exists, but it could not be read as UTF-8 JSON; source contents and RPC details remain unverified.",
    })
    print(json.dumps(result, ensure_ascii=False, indent=2))
    sys.exit(0)

result.update({
    "archive_recovered": True,
    "archive_path": str(archive_path),
    "archive_bytes": len(raw),
    "actual_sha256": actual_sha,
    "sha256_matches_supplied": actual_sha == EXPECTED_SHA256,
    "json_root_type": type(document).__name__,
})

if not isinstance(document, dict) or SOURCE_KEY not in document:
    result.update({
        "source_accessed": False,
        "limitation": "The archive was read, but the supplied JSON source path prior_observations was not present at the document root.",
    })
    print(json.dumps(result, ensure_ascii=False, indent=2))
    sys.exit(0)

source = document[SOURCE_KEY]
encoded_source = json.dumps(source, ensure_ascii=False, separators=(",", ":")).encode("utf-8")
needles = ("rpc", "nfs", "mount", "showmount", "portmapper", "port map")
matches = []
record_count = 0

def visit(value):
    global record_count
    if isinstance(value, dict):
        if "node_id" in value:
            record_count += 1
            searchable = json.dumps(value, ensure_ascii=False, sort_keys=True).lower()
            if any(term in searchable for term in needles):
                matches.append(value)
        for child in value.values():
            visit(child)
    elif isinstance(value, list):
        for child in value:
            visit(child)

visit(source)
result.update({
    "source_accessed": True,
    "source_type": type(source).__name__,
    "source_compact_json_bytes": len(encoded_source),
    "record_objects_examined": record_count,
    "rpc_relevant_record_count": len(matches),
    "matching_records": matches,
    "coverage_note": "Matching complete record objects from the archived prior_observations value are emitted verbatim. The search identifies records containing RPC/NFS/MOUNT-related terms; it does not infer endpoints, services, versions, or unexamined evidence.",
})
if not matches:
    result["coverage_note"] += " No matching record objects were found by these terms in the accessed source; this is limited to this source value and matching rule."

print(json.dumps(result, ensure_ascii=False, indent=2))

