import hashlib
import json
import os
import sys
from pathlib import Path

EXPECTED_NAME = "b2e16ded3971bba03a2bb30e31a02b9847f8790f2903c9c6ab63cc7b0d8380d8.json"
EXPECTED_SHA256 = EXPECTED_NAME[:-5]
TERMS = ("rpc", "mount", "nfs", "portmapper", "portmap", "mountd")
PRUNE = {"proc", "sys", "dev", "node_modules", ".git", "__pycache__"}


def main():
    cwd = Path.cwd()
    direct = [
        cwd / "llm_inputs" / EXPECTED_NAME,
        cwd / EXPECTED_NAME,
        Path("/root/scripts/llm_inputs") / EXPECTED_NAME,
        Path("/root/scripts") / EXPECTED_NAME,
        Path("/root/llm_inputs") / EXPECTED_NAME,
        Path("/root") / EXPECTED_NAME,
        Path("/tmp/llm_inputs") / EXPECTED_NAME,
        Path("/tmp") / EXPECTED_NAME,
        Path("/workspace/llm_inputs") / EXPECTED_NAME,
        Path("/workspace") / EXPECTED_NAME,
        Path("/app/llm_inputs") / EXPECTED_NAME,
        Path("/app") / EXPECTED_NAME,
        Path("/mnt/data/llm_inputs") / EXPECTED_NAME,
        Path("/mnt/data") / EXPECTED_NAME,
    ]
    roots = [cwd, Path("/root"), Path("/tmp"), Path("/workspace"),
             Path("/app"), Path("/mnt/data")]
    checked = []
    found = {}
    errors = []

    for p in direct:
        try:
            resolved = p.resolve(strict=False)
            checked.append(str(resolved))
            if p.is_file() and p.name == EXPECTED_NAME:
                found[str(p.resolve())] = p.resolve()
        except OSError as exc:
            errors.append({"path": str(p), "error": str(exc)})

    # Search only the named artifact, not other hashes or archive contents.
    visited = set()
    for root in roots:
        try:
            root = root.resolve(strict=True)
        except OSError as exc:
            errors.append({"path": str(root), "error": str(exc)})
            continue
        if not root.is_dir() or str(root) in visited:
            continue
        visited.add(str(root))
        checked.append(str(root) + "/**/" + EXPECTED_NAME)
        for current, dirs, files in os.walk(root, topdown=True, followlinks=False,
                                             onerror=lambda e: errors.append({"path": getattr(e, "filename", ""), "error": str(e)})):
            dirs[:] = [d for d in dirs if d not in PRUNE and not os.path.islink(os.path.join(current, d))]
            if EXPECTED_NAME in files:
                p = Path(current) / EXPECTED_NAME
                try:
                    found[str(p.resolve())] = p.resolve()
                except OSError as exc:
                    errors.append({"path": str(p), "error": str(exc)})

    results = []
    for source, path in sorted(found.items()):
        item = {"source_path": source}
        try:
            data = path.read_bytes()
            digest = hashlib.sha256(data).hexdigest()
            item.update({"size_bytes": len(data), "sha256": digest,
                         "sha256_matches_filename": digest == EXPECTED_SHA256})
            observations = []
            parse_status = "json"
            try:
                parsed = json.loads(data.decode("utf-8"))

                def visit(value, location="$", seen=None):
                    if seen is None:
                        seen = set()
                    if isinstance(value, dict):
                        for key, child in value.items():
                            child_path = location + "[" + json.dumps(str(key), ensure_ascii=False) + "]"
                            if any(term in str(key).lower() for term in TERMS):
                                observations.append({"path": child_path, "value": child})
                            visit(child, child_path, seen)
                    elif isinstance(value, list):
                        for index, child in enumerate(value):
                            visit(child, location + "[" + str(index) + "]", seen)
                    elif isinstance(value, str) and any(term in value.lower() for term in TERMS):
                        marker = (location, value)
                        if marker not in seen:
                            seen.add(marker)
                            observations.append({"path": location, "value": value})
                visit(parsed)
            except (UnicodeDecodeError, json.JSONDecodeError) as exc:
                parse_status = "not_valid_utf8_json: " + str(exc)
                text = data.decode("utf-8", errors="replace")
                for number, line in enumerate(text.splitlines(), 1):
                    if any(term in line.lower() for term in TERMS):
                        observations.append({"line": number, "value": line})
            item.update({"parse_status": parse_status,
                         "rpc_mount_nfs_observations": observations,
                         "matching_observation_count": len(observations),
                         "inspection_coverage": "Entire decoded JSON value tree inspected for relevant keys and strings; for non-JSON input, all decoded lines inspected for relevant terms."})
        except OSError as exc:
            item["read_error"] = str(exc)
        results.append(item)

    output = {
        "requested_artifact": "llm_inputs/" + EXPECTED_NAME,
        "expected_sha256": EXPECTED_SHA256,
        "checked_locations": checked,
        "search_errors": errors,
        "found_exact_filename_count": len(results),
        "artifacts": results,
        "result": ("exact-named artifact inspected" if results else
                   "exact-named artifact not found at checked paths or within searched roots; this does not establish absence elsewhere")
    }
    print(json.dumps(output, ensure_ascii=False, indent=2))


if __name__ == "__main__":
    main()

