import json
import secrets
import socket
import struct

HOSTS = ["192.168.0.1", "192.168.65.3", "192.168.65.6"]
REGISTRY_PORT = 111
VERSIONS = [2, 3, 4]
TIMEOUT = 2.0
MAX_REPLY = 1024 * 1024


def pack_uint(value):
    return struct.pack("!I", value)


def make_call(xid, version):
    # ONC RPC CALL, RPC version 2, program 100000 (portmapper/rpcbind),
    # requested registry version, procedure 4 (DUMP), AUTH_NULL credential
    # and verifier.
    return b"".join([
        pack_uint(xid), pack_uint(0), pack_uint(2), pack_uint(100000),
        pack_uint(version), pack_uint(4), pack_uint(0), pack_uint(0),
        pack_uint(0), pack_uint(0)
    ])


def read_uint(data, offset):
    if offset + 4 > len(data):
        raise ValueError("truncated XDR uint")
    return struct.unpack_from("!I", data, offset)[0], offset + 4


def read_xdr_string(data, offset):
    length, offset = read_uint(data, offset)
    end = offset + length
    padded_end = offset + ((length + 3) // 4) * 4
    if padded_end > len(data):
        raise ValueError("truncated XDR string")
    value = data[offset:end].decode("utf-8", errors="replace")
    return value, padded_end


def parse_reply(data, xid, version):
    offset = 0
    got_xid, offset = read_uint(data, offset)
    if got_xid != xid:
        raise ValueError("response XID does not match request")
    message_type, offset = read_uint(data, offset)
    if message_type != 1:
        raise ValueError("response is not an RPC REPLY")
    reply_stat, offset = read_uint(data, offset)
    if reply_stat != 0:
        if reply_stat == 1:
            reject_stat, offset = read_uint(data, offset)
            detail = {"reply_status": "denied", "reject_status": reject_stat}
            if reject_stat == 0:
                low, offset = read_uint(data, offset)
                high, offset = read_uint(data, offset)
                detail["rpc_version_range"] = [low, high]
            elif reject_stat == 1:
                auth_stat, offset = read_uint(data, offset)
                detail["auth_status"] = auth_stat
            return {"status": "rpc_error", "error": detail}
        return {"status": "rpc_error", "error": {"reply_status": reply_stat}}

    # Accepted reply: verifier opaque_auth, followed by accept_stat.
    _flavor, offset = read_uint(data, offset)
    verifier_len, offset = read_uint(data, offset)
    verifier_end = offset + verifier_len
    offset = offset + ((verifier_len + 3) // 4) * 4
    if offset > len(data):
        raise ValueError("truncated RPC verifier")
    accept_stat, offset = read_uint(data, offset)
    if accept_stat != 0:
        return {
            "status": "rpc_error",
            "error": {"accept_status": accept_stat}
        }

    mappings = []
    while True:
        present, offset = read_uint(data, offset)
        if present == 0:
            break
        if present != 1:
            raise ValueError("invalid XDR linked-list boolean")
        if version == 2:
            program, offset = read_uint(data, offset)
            program_version, offset = read_uint(data, offset)
            protocol, offset = read_uint(data, offset)
            port, offset = read_uint(data, offset)
            protocol_name = {6: "tcp", 17: "udp"}.get(protocol, "unknown")
            mappings.append({
                "program": program,
                "program_version": program_version,
                "protocol_number": protocol,
                "protocol": protocol_name,
                "port": port,
                "endpoint": f"{protocol_name}:{port}"
            })
        else:
            netid, offset = read_xdr_string(data, offset)
            universal_address, offset = read_xdr_string(data, offset)
            owner, offset = read_xdr_string(data, offset)
            mappings.append({
                "netid": netid,
                "universal_address": universal_address,
                "owner": owner,
                "endpoint": universal_address
            })
    return {"status": "success", "mappings": mappings}


def recv_exact(sock, count):
    chunks = []
    remaining = count
    while remaining:
        chunk = sock.recv(remaining)
        if not chunk:
            raise OSError("connection closed before complete RPC record")
        chunks.append(chunk)
        remaining -= len(chunk)
    return b"".join(chunks)


def tcp_record(sock):
    chunks = []
    total = 0
    while True:
        marker = struct.unpack("!I", recv_exact(sock, 4))[0]
        last_fragment = bool(marker & 0x80000000)
        length = marker & 0x7fffffff
        total += length
        if total > MAX_REPLY:
            raise ValueError("RPC record exceeds local 1 MiB response limit")
        chunks.append(recv_exact(sock, length))
        if last_fragment:
            return b"".join(chunks)


def query(host, transport, version):
    xid = secrets.randbits(32)
    request = make_call(xid, version)
    result = {
        "host": host,
        "registry_port": REGISTRY_PORT,
        "transport": transport,
        "rpcbind_version": version,
        "procedure": "DUMP",
        "procedure_number": 4,
        "request_hex": request.hex()
    }
    sock = None
    try:
        if transport == "udp":
            sock = socket.socket(socket.AF_INET, socket.SOCK_DGRAM)
            sock.settimeout(TIMEOUT)
            sock.sendto(request, (host, REGISTRY_PORT))
            response, peer = sock.recvfrom(65535)
            result["response_source"] = {"host": peer[0], "port": peer[1]}
        else:
            sock = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
            sock.settimeout(TIMEOUT)
            sock.connect((host, REGISTRY_PORT))
            sock.sendall(struct.pack("!I", 0x80000000 | len(request)) + request)
            response = tcp_record(sock)
            result["response_source"] = {"host": host, "port": REGISTRY_PORT}
        result["response_hex"] = response.hex()
        try:
            result.update(parse_reply(response, xid, version))
        except (ValueError, struct.error) as exc:
            result["status"] = "parse_error"
            result["error"] = str(exc)
    except (OSError, ValueError, struct.error) as exc:
        result["status"] = "no_complete_response"
        result["error"] = f"{type(exc).__name__}: {exc}"
    finally:
        if sock is not None:
            sock.close()
    return result


def main():
    attempts = []
    for host in HOSTS:
        for transport in ("udp", "tcp"):
            for version in VERSIONS:
                attempts.append(query(host, transport, version))
    findings = []
    for attempt in attempts:
        if attempt.get("status") == "success" and attempt.get("mappings"):
            findings.append({
                "host": attempt["host"],
                "registry_transport": attempt["transport"],
                "registry_port": attempt["registry_port"],
                "rpcbind_version": attempt["rpcbind_version"],
                "mappings": attempt["mappings"]
            })
    print(json.dumps({
        "scope": HOSTS,
        "excluded_host": "192.168.122.1",
        "examination": {
            "registry_port": REGISTRY_PORT,
            "transports_attempted": ["udp", "tcp"],
            "rpcbind_versions_attempted": VERSIONS,
            "attempt_count": len(attempts),
            "timeout_seconds_per_socket_operation": TIMEOUT,
            "coverage_note": "Only RPC registry DUMP requests to port 111 for versions 2, 3, and 4 over UDP and TCP were attempted. No other ports or endpoints were guessed."
        },
        "observed_mappings": findings,
        "attempts": attempts
    }, sort_keys=True))


if __name__ == "__main__":
    main()

