import json
import socket
import struct
import time

HOSTS = ["192.168.0.1", "192.168.65.3", "192.168.65.6"]
REGISTRY_PORT = 111
RPCB_VERSIONS = [2, 3, 4]
TIMEOUT_SECONDS = 2.0
MAX_REPLY_BYTES = 1_048_576


def pad4(data):
    return data + b"\x00" * ((-len(data)) % 4)


def rpc_call(xid, rpc_version):
    # AUTH_NULL credential and verifier; RPCBPROC_DUMP is procedure 4.
    words = [xid, 0, 2, 100000, rpc_version, 4, 0, 0, 0, 0]
    return struct.pack(">10I", *words)


def read_exact(sock, size):
    chunks = []
    remaining = size
    while remaining:
        chunk = sock.recv(remaining)
        if not chunk:
            raise EOFError("connection closed before complete RPC record")
        chunks.append(chunk)
        remaining -= len(chunk)
    return b"".join(chunks)


def read_tcp_record(sock):
    chunks = []
    total = 0
    while True:
        marker = struct.unpack(">I", read_exact(sock, 4))[0]
        fragment_size = marker & 0x7fffffff
        total += fragment_size
        if total > MAX_REPLY_BYTES:
            raise ValueError("RPC record exceeds configured parsing bound")
        chunks.append(read_exact(sock, fragment_size))
        if marker & 0x80000000:
            break
    return b"".join(chunks)


class XDRReader:
    def __init__(self, data):
        self.data = data
        self.offset = 0

    def uint(self):
        if self.offset + 4 > len(self.data):
            raise ValueError("truncated XDR uint")
        value = struct.unpack_from(">I", self.data, self.offset)[0]
        self.offset += 4
        return value

    def string(self):
        length = self.uint()
        if length > MAX_REPLY_BYTES or self.offset + length > len(self.data):
            raise ValueError("truncated or oversized XDR string")
        value = self.data[self.offset:self.offset + length]
        self.offset += length
        self.offset += (-length) % 4
        if self.offset > len(self.data):
            raise ValueError("truncated XDR string padding")
        return value.decode("utf-8", errors="replace")


def parse_reply(data, expected_xid, rpc_version):
    reader = XDRReader(data)
    xid = reader.uint()
    if xid != expected_xid:
        raise ValueError("RPC transaction ID mismatch")
    message_type = reader.uint()
    if message_type != 1:
        raise ValueError("message is not an RPC reply")
    reply_status = reader.uint()
    if reply_status != 0:
        return {"rpc_reply_status": reply_status}
    verifier_flavor = reader.uint()
    verifier_length = reader.uint()
    if verifier_length > MAX_REPLY_BYTES or reader.offset + verifier_length > len(data):
        raise ValueError("truncated RPC verifier")
    reader.offset += verifier_length + ((-verifier_length) % 4)
    accept_status = reader.uint()
    if accept_status != 0:
        return {"rpc_reply_status": "accepted", "accept_status": accept_status,
                "verifier_flavor": verifier_flavor}

    mappings = []
    count = 0
    while True:
        present = reader.uint()
        if present == 0:
            break
        if present != 1:
            raise ValueError("invalid XDR linked-list boolean")
        count += 1
        if count > 10000:
            raise ValueError("mapping list exceeds parsing bound")
        if rpc_version == 2:
            program = reader.uint()
            program_version = reader.uint()
            protocol_number = reader.uint()
            port = reader.uint()
            mappings.append({
                "program": program,
                "program_version": program_version,
                "protocol_number": protocol_number,
                "transport": {6: "tcp", 17: "udp"}.get(protocol_number, "unknown"),
                "port": port,
                "endpoint": "{}:{}".format(
                    {6: "tcp", 17: "udp"}.get(protocol_number, "unknown"), port)
            })
        else:
            mappings.append({
                "program": reader.uint(),
                "program_version": reader.uint(),
                "netid": reader.string(),
                "universal_address": reader.string(),
                "owner": reader.string()
            })
    return {
        "rpc_reply_status": "accepted",
        "accept_status": "success",
        "verifier_flavor": verifier_flavor,
        "mappings": mappings
    }


def query(host, transport, rpc_version, xid):
    record = {
        "host": host,
        "registry_endpoint": "{}:{}".format(transport, REGISTRY_PORT),
        "rpc_program": 100000,
        "rpc_version": rpc_version,
        "procedure": "DUMP",
        "procedure_number": 4,
        "status": "error"
    }
    request = rpc_call(xid, rpc_version)
    sock = None
    try:
        family = socket.AF_INET
        socktype = socket.SOCK_DGRAM if transport == "udp" else socket.SOCK_STREAM
        sock = socket.socket(family, socktype)
        sock.settimeout(TIMEOUT_SECONDS)
        if transport == "udp":
            sock.sendto(request, (host, REGISTRY_PORT))
            response, source = sock.recvfrom(65535)
            record["response_source"] = {"host": source[0], "port": source[1]}
        else:
            sock.connect((host, REGISTRY_PORT))
            sock.sendall(struct.pack(">I", 0x80000000 | len(request)) + request)
            response = read_tcp_record(sock)
            record["response_source"] = {"host": host, "port": REGISTRY_PORT}
        record["response_hex"] = response.hex()
        record["response_bytes"] = len(response)
        try:
            record["decoded"] = parse_reply(response, xid, rpc_version)
            record["status"] = "response_received"
        except Exception as exc:
            record["parse_error"] = "{}: {}".format(type(exc).__name__, exc)
            record["status"] = "response_received_parse_inconclusive"
    except Exception as exc:
        record["error"] = "{}: {}".format(type(exc).__name__, exc)
        record["status"] = "interaction_error"
    finally:
        if sock is not None:
            sock.close()
    return record


def main():
    results = []
    xid = (int(time.time()) ^ (int(time.monotonic_ns()) & 0xffffffff)) & 0xffffffff
    for host_index, host in enumerate(HOSTS):
        for transport_index, transport in enumerate(("tcp", "udp")):
            for version_index, rpc_version in enumerate(RPCB_VERSIONS):
                query_xid = (xid + host_index * 100 + transport_index * 10 + version_index) & 0xffffffff
                results.append(query(host, transport, rpc_version, query_xid))
    summary = {
        "purpose": "Query only previously identified rpcbind registry endpoints; no additional endpoints were guessed.",
        "scope": HOSTS,
        "registry_port": REGISTRY_PORT,
        "transports_queried": ["tcp", "udp"],
        "rpcbind_versions_queried": RPCB_VERSIONS,
        "query_count": len(results),
        "response_count": sum(r["status"].startswith("response_received") for r in results),
        "results": results
    }
    print(json.dumps(summary, sort_keys=True))


if __name__ == "__main__":
    main()

