import json
import socket
import struct
import secrets

HOSTS = ["192.168.0.1", "192.168.65.3", "192.168.65.6"]
PORT = 111
TIMEOUT = 3.0
MOUNT_NFS = {100003: "NFS", 100005: "MOUNT"}


def u32(value):
    return struct.pack("!I", value)


def make_call(xid):
    # RPC v2 CALL to rpcbind v2, DUMP procedure, with AUTH_NONE credentials.
    return b"".join([
        u32(xid), u32(0), u32(2), u32(100000), u32(2), u32(4),
        u32(0), u32(0), u32(0), u32(0),
    ])


def read_u32(data, offset):
    if offset + 4 > len(data):
        raise ValueError("truncated XDR uint32")
    return struct.unpack_from("!I", data, offset)[0], offset + 4


def decode_reply(data, expected_xid):
    offset = 0
    xid, offset = read_u32(data, offset)
    if xid != expected_xid:
        raise ValueError("reply transaction ID did not match request")
    msg_type, offset = read_u32(data, offset)
    if msg_type != 1:
        raise ValueError("RPC message is not a REPLY")
    reply_stat, offset = read_u32(data, offset)
    if reply_stat != 0:
        raise ValueError("RPC reply was denied (reply status %d)" % reply_stat)
    _flavor, offset = read_u32(data, offset)
    verifier_len, offset = read_u32(data, offset)
    padded_len = (verifier_len + 3) & ~3
    if offset + padded_len > len(data):
        raise ValueError("truncated RPC verifier")
    offset += padded_len
    accept_stat, offset = read_u32(data, offset)
    if accept_stat != 0:
        raise ValueError("RPC call was not accepted (accept status %d)" % accept_stat)

    mappings = []
    # rpcbind v2 DUMP is a linked list: bool, then (prog, vers, protocol, port).
    while True:
        present, offset = read_u32(data, offset)
        if present == 0:
            break
        if present != 1:
            raise ValueError("invalid XDR linked-list marker")
        program, offset = read_u32(data, offset)
        version, offset = read_u32(data, offset)
        protocol, offset = read_u32(data, offset)
        port, offset = read_u32(data, offset)
        mappings.append({
            "program": program,
            "program_name": MOUNT_NFS.get(program, "other"),
            "program_version": version,
            "transport": {6: "tcp", 17: "udp"}.get(protocol, "protocol_%d" % protocol),
            "port": port,
        })
    if offset != len(data):
        raise ValueError("unexpected trailing bytes after rpcbind DUMP list")
    return mappings


def tcp_exchange(host, request):
    with socket.create_connection((host, PORT), timeout=TIMEOUT) as sock:
        sock.settimeout(TIMEOUT)
        sock.sendall(struct.pack("!I", 0x80000000 | len(request)) + request)
        marker = recv_exact(sock, 4)
        record_marker = struct.unpack("!I", marker)[0]
        length = record_marker & 0x7fffffff
        if length > 1_000_000:
            raise ValueError("TCP RPC record exceeds safety bound")
        body = recv_exact(sock, length)
        while not (record_marker & 0x80000000):
            marker = recv_exact(sock, 4)
            record_marker = struct.unpack("!I", marker)[0]
            length = record_marker & 0x7fffffff
            if length > 1_000_000:
                raise ValueError("TCP RPC fragment exceeds safety bound")
            body += recv_exact(sock, length)
        return body


def recv_exact(sock, count):
    chunks = bytearray()
    while len(chunks) < count:
        part = sock.recv(count - len(chunks))
        if not part:
            raise ConnectionError("connection closed before complete RPC record")
        chunks.extend(part)
    return bytes(chunks)


def udp_exchange(host, request):
    with socket.socket(socket.AF_INET, socket.SOCK_DGRAM) as sock:
        sock.settimeout(TIMEOUT)
        sock.sendto(request, (host, PORT))
        response, source = sock.recvfrom(65535)
        if source[0] != host:
            raise ValueError("UDP reply source address did not match queried host")
        return response


def query(host, transport):
    xid = secrets.randbits(32)
    request = make_call(xid)
    try:
        response = tcp_exchange(host, request) if transport == "tcp" else udp_exchange(host, request)
        mappings = decode_reply(response, xid)
        selected = [m for m in mappings if m["program"] in MOUNT_NFS]
        return {
            "transport_to_registry": transport,
            "registry_endpoint": "%s:111/%s" % (host, transport),
            "status": "response_received_and_parsed",
            "mapping_count": len(mappings),
            "mount_nfs_mappings": selected,
        }
    except (OSError, ValueError, ConnectionError, struct.error) as exc:
        return {
            "transport_to_registry": transport,
            "registry_endpoint": "%s:111/%s" % (host, transport),
            "status": "inconclusive",
            "error": "%s: %s" % (type(exc).__name__, str(exc)),
        }


def main():
    results = []
    for host in HOSTS:
        queries = [query(host, transport) for transport in ("tcp", "udp")]
        conclusive = all(item["status"] == "response_received_and_parsed" for item in queries)
        mappings = [mapping for item in queries for mapping in item.get("mount_nfs_mappings", [])]
        results.append({
            "host": host,
            "registry_port": PORT,
            "queries": queries,
            "coverage_status": "conclusive" if conclusive else "inconclusive",
            "mount_nfs_mappings_returned": mappings,
            "conclusive_no_mount_nfs_mapping": conclusive and not mappings,
        })
    print(json.dumps({
        "purpose": "Focused rpcbind v2 DUMP follow-up; only previously identified hosts queried.",
        "hosts_queried": HOSTS,
        "rpcbind_version": 2,
        "procedure": "DUMP",
        "results": results,
    }, separators=(",", ":")))


if __name__ == "__main__":
    main()
